css:
/* Layout: module rail on the right (RTL) + working canvas; tables are the main surface, charts sit beside their summaries */
:root{
  --bg:#ECF0EF; --surface:#FFFFFF; --surface-2:#F4F7F6; --ink:#13201E; --muted:#5A6967; --line:#D2DBD9;
  --accent:#157B98; --accent-soft:#DCEEF3; --accent-ink:#FFFFFF;
  --sand:#B97D1F; --sand-soft:#F7ECD8;
  --ok:#2B7749; --ok-soft:#E0F0E6; --warn:#9F640C; --warn-soft:#FAEED6; --crit:#B3261E; --crit-soft:#FAE2DF; --info:#2B5D9B; --info-soft:#E1EAF6;
  --f-display:"Noto Kufi Arabic","IBM Plex Sans Arabic",Tahoma,sans-serif;
  --f-body:"IBM Plex Sans Arabic",Tahoma,"Segoe UI",sans-serif;
  --f-mono:"IBM Plex Mono",ui-monospace,Menlo,Consolas,monospace;
  --r:8px;
}
@media (prefers-color-scheme: dark){:root:not([data-theme="light"]){
  --bg:#0D1413; --surface:#141D1C; --surface-2:#1A2524; --ink:#E2EBE9; --muted:#93A4A1; --line:#283533;
  --accent:#4FB3CF; --accent-soft:#143440; --accent-ink:#06191B;
  --sand:#E0A94C; --sand-soft:#3A2D16;
  --ok:#5CBD86; --ok-soft:#173226; --warn:#E2AA4C; --warn-soft:#3A2C12; --crit:#EE6D63; --crit-soft:#3E1C19; --info:#7AA7E0; --info-soft:#18273A;
  color-scheme:dark}}
:root[data-theme="dark"]{
  --bg:#0D1413; --surface:#141D1C; --surface-2:#1A2524; --ink:#E2EBE9; --muted:#93A4A1; --line:#283533;
  --accent:#4FB3CF; --accent-soft:#143440; --accent-ink:#06191B;
  --sand:#E0A94C; --sand-soft:#3A2D16;
  --ok:#5CBD86; --ok-soft:#173226; --warn:#E2AA4C; --warn-soft:#3A2C12; --crit:#EE6D63; --crit-soft:#3E1C19; --info:#7AA7E0; --info-soft:#18273A;
  color-scheme:dark}
*{box-sizing:border-box}
body{background:var(--bg);color:var(--ink);font-family:var(--f-body);font-size:14px;line-height:1.6}
body::before{content:"";position:fixed;inset:0 0 auto;height:env(safe-area-inset-top,0px);z-index:10;background:var(--surface)}
h1,h2,h3{font-family:var(--f-display);text-wrap:balance;margin:0;line-height:1.35}
h1{font-size:1.15rem}h2{font-size:1.05rem}h3{font-size:.92rem}
button,input,select,textarea{font:inherit;color:inherit}
.num,td.n,th.n{font-variant-numeric:tabular-nums}
.mono{font-family:var(--f-mono);font-size:.86em;letter-spacing:.01em}
.muted{color:var(--muted)}
.app{display:grid;grid-template-columns:236px minmax(0,1fr);min-height:100vh}
.side{background:var(--surface);border-inline-start:1px solid var(--line);position:sticky;top:env(safe-area-inset-top,0px);height:100vh;overflow:auto;padding-block:18px;padding-inline:12px;display:flex;flex-direction:column;gap:14px}
.brand{padding-inline:6px;display:grid;gap:2px}
.brand small{color:var(--muted);font-size:.75rem}
.brand .mark{font-family:var(--f-display);font-size:1rem;color:var(--accent)}
nav{display:grid;gap:2px}
nav button{display:flex;align-items:center;gap:10px;padding:9px 10px;border:0;background:none;border-radius:6px;cursor:pointer;text-align:start;color:var(--ink)}
nav button .tag{font-family:var(--f-mono);font-size:.7rem;width:22px;height:22px;display:grid;place-items:center;border-radius:4px;background:var(--surface-2);color:var(--muted);flex:none}
nav button:hover{background:var(--surface-2)}
nav button[aria-current="true"]{background:var(--accent-soft);color:var(--accent);font-weight:600}
nav button[aria-current="true"] .tag{background:var(--accent);color:var(--accent-ink)}
.side .foot{margin-top:auto;font-size:.75rem;color:var(--muted);padding-inline:6px}
.main{min-width:0;display:flex;flex-direction:column}
.top{position:sticky;top:env(safe-area-inset-top,0px);z-index:5;background:var(--surface);border-bottom:1px solid var(--line);padding-block:10px;padding-left:max(16px,env(safe-area-inset-left,0px));padding-right:max(16px,env(safe-area-inset-right,0px));display:flex;flex-wrap:wrap;gap:10px 16px;align-items:center}
.top .ttl{display:grid;min-width:0;flex:1 1 260px}
.top .ttl small{color:var(--muted);font-size:.78rem}
.ctrl{display:flex;gap:8px;align-items:center;flex-wrap:wrap}
.content{padding-block:20px 48px;padding-left:max(16px,env(safe-area-inset-left,0px));padding-right:max(16px,env(safe-area-inset-right,0px));display:grid;gap:18px;min-width:0}
.vh{display:flex;flex-wrap:wrap;gap:8px 16px;align-items:flex-end;justify-content:space-between}
.vh p{margin:2px 0 0;color:var(--muted);max-width:70ch}
.card{background:var(--surface);border:1px solid var(--line);border-radius:var(--r);padding:16px;min-width:0;display:grid;gap:12px;align-content:start}
.card>header{display:flex;flex-wrap:wrap;gap:8px;align-items:center;justify-content:space-between}
.grid{display:grid;gap:16px}
.g2{grid-template-columns:repeat(2,minmax(0,1fr))}
.g3{grid-template-columns:repeat(3,minmax(0,1fr))}
.g4{grid-template-columns:repeat(4,minmax(0,1fr))}
.span2{grid-column:span 2}
@media (max-width:1100px){.g4{grid-template-columns:repeat(2,minmax(0,1fr))}.g3{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media (max-width:700px){.g2,.g3,.g4{grid-template-columns:minmax(0,1fr)}.span2{grid-column:auto}}
.kpi{background:var(--surface);border:1px solid var(--line);border-radius:var(--r);padding:14px 16px;display:grid;gap:4px;align-content:start}
.kpi .lb{font-size:.78rem;color:var(--muted);letter-spacing:.01em}
.kpi .v{font-family:var(--f-mono);font-size:1.55rem;font-weight:500;font-variant-numeric:tabular-nums;line-height:1.2}
.kpi .v small{font-size:.8rem;color:var(--muted);font-family:var(--f-body)}
.kpi .s{font-size:.8rem;color:var(--muted)}
.btn{border:1px solid var(--line);background:var(--surface);padding:6px 12px;border-radius:6px;cursor:pointer;font-size:.86rem;white-space:nowrap}
.btn:hover{border-color:var(--accent);color:var(--accent)}
.btn.pri{background:var(--accent);border-color:var(--accent);color:var(--accent-ink)}
.btn.pri:hover{filter:brightness(1.08);color:var(--accent-ink)}
.btn.sm{padding:3px 9px;font-size:.8rem}
.btn[disabled]{opacity:.45;cursor:not-allowed}
.btn:focus-visible,nav button:focus-visible,select:focus-visible,input:focus-visible,textarea:focus-visible,.tabs button:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
select,input[type=text],input[type=number],input[type=date],textarea{background:var(--surface-2);border:1px solid var(--line);border-radius:6px;padding:6px 9px;min-width:0;max-width:100%}
.fld{display:grid;gap:4px;font-size:.8rem;color:var(--muted);min-width:0}
.fld>*:not(span){color:var(--ink);font-size:.88rem}
.form{display:grid;gap:10px;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));align-items:end}
.tabs{display:flex;gap:4px;border-bottom:1px solid var(--line);overflow-x:auto}
.tabs button{border:0;background:none;padding:8px 12px;cursor:pointer;color:var(--muted);border-bottom:2px solid transparent;white-space:nowrap}
.tabs button[aria-selected="true"]{color:var(--accent);border-bottom-color:var(--accent);font-weight:600}
.tw{overflow-x:auto;border:1px solid var(--line);border-radius:6px}
table.d{width:100%;border-collapse:collapse;font-size:.84rem}
table.d th{background:var(--surface-2);color:var(--muted);font-weight:500;text-align:start;padding:7px 9px;border-bottom:1px solid var(--line);white-space:nowrap;font-size:.76rem;letter-spacing:.01em}
table.d td{padding:7px 9px;border-bottom:1px solid var(--line);vertical-align:top}
table.d tr:last-child td{border-bottom:0}
table.d td.n,table.d th.n{text-align:left;direction:ltr;font-variant-numeric:tabular-nums;white-space:nowrap}
table.d tr.sel td{background:var(--accent-soft)}
table.d tr.click{cursor:pointer}
table.d tr.click:hover td{background:var(--surface-2)}
table.d tr.grp td{background:var(--surface-2);font-weight:600;font-size:.8rem}
table.d tfoot td{font-weight:600;background:var(--surface-2)}
.desc{min-width:240px;max-width:420px}
.pill{display:inline-flex;align-items:center;gap:4px;padding:1px 8px;border-radius:99px;font-size:.74rem;font-weight:500;white-space:nowrap;background:var(--surface-2);color:var(--muted);border:1px solid var(--line)}
.pill.ok{background:var(--ok-soft);color:var(--ok);border-color:transparent}
.pill.warn{background:var(--warn-soft);color:var(--warn);border-color:transparent}
.pill.crit{background:var(--crit-soft);color:var(--crit);border-color:transparent}
.pill.info{background:var(--info-soft);color:var(--info);border-color:transparent}
.pill.acc{background:var(--accent-soft);color:var(--accent);border-color:transparent}
.meter{height:7px;border-radius:99px;background:var(--surface-2);border:1px solid var(--line);overflow:hidden;direction:ltr;position:relative;min-width:60px}
.meter>i{display:block;height:100%;background:var(--accent)}
.meter>i.warn{background:var(--warn)}.meter>i.crit{background:var(--crit)}.meter>i.ok{background:var(--ok)}.meter>i.sand{background:var(--sand)}
.meter>b{position:absolute;top:-2px;bottom:-2px;width:2px;background:var(--ink)}
.bars{display:grid;gap:10px}
.bar-row{display:grid;grid-template-columns:120px minmax(0,1fr) 110px;gap:10px;align-items:center;font-size:.84rem}
.bar-row .meter{height:12px}
.bar-row .n{text-align:left;direction:ltr;font-family:var(--f-mono);font-size:.8rem}
@media (max-width:520px){.bar-row{grid-template-columns:90px minmax(0,1fr);}.bar-row .n{grid-column:2}}
.list{display:grid;gap:0}
.li{display:flex;gap:10px;align-items:flex-start;justify-content:space-between;padding:9px 0;border-bottom:1px solid var(--line);font-size:.85rem}
.li:last-child{border-bottom:0}
.li .t{min-width:0}
.li .t small{display:block;color:var(--muted);font-size:.76rem}
.stripe{border-inline-start:3px solid var(--line);padding-inline-start:10px}
.stripe.crit{border-color:var(--crit)}.stripe.warn{border-color:var(--warn)}.stripe.ok{border-color:var(--ok)}
.chart{direction:ltr;width:100%;overflow-x:auto}
.chart svg{display:block;width:100%;height:auto;min-width:520px}
.chart text{font-family:var(--f-body);fill:var(--muted);font-size:11px}
.legend{display:flex;flex-wrap:wrap;gap:14px;font-size:.8rem;color:var(--muted)}
.legend i{display:inline-block;width:14px;height:3px;border-radius:2px;vertical-align:middle;margin-inline-end:6px}
.check{display:grid;gap:6px;padding:12px;border-radius:6px;background:var(--surface-2);border:1px solid var(--line);font-size:.84rem}
.check.bad{border-color:var(--crit);background:var(--crit-soft)}
.check.good{border-color:var(--ok);background:var(--ok-soft)}
.formula{font-family:var(--f-mono);direction:ltr;text-align:left;font-size:.82rem}
/* gantt */
.gantt{border:1px solid var(--line);border-radius:6px;overflow-x:auto}
.gr{display:grid;grid-template-columns:230px minmax(560px,1fr);border-bottom:1px solid var(--line);min-width:790px}
.gr:last-child{border-bottom:0}
.gr .nm{padding:6px 10px;font-size:.8rem;border-inline-end:1px solid var(--line);display:flex;gap:6px;align-items:center;min-width:0}
.gr .nm span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.gr .tr{position:relative;direction:ltr;height:32px}
.gr.hd{background:var(--surface-2);font-size:.72rem;color:var(--muted)}
.gr.hd .tr{height:28px}
.tick{position:absolute;top:0;bottom:0;border-left:1px dashed var(--line);font-size:.7rem;color:var(--muted);padding-left:3px;white-space:nowrap}
.gb{position:absolute;top:9px;height:14px;border-radius:3px;background:var(--accent-soft);border:1px solid var(--accent);overflow:hidden}
.gb.cr{background:var(--crit-soft);border-color:var(--crit)}
.gb i{position:absolute;inset:0 auto 0 0;background:var(--accent)}
.gb.cr i{background:var(--crit)}
.dd{position:absolute;top:0;bottom:0;width:0;border-left:2px solid var(--sand);z-index:2}
.ce{position:absolute;top:0;bottom:0;width:0;border-left:2px dotted var(--muted)}
/* snag plan */
.plan{direction:ltr;max-width:640px}
.plan svg{width:100%;height:auto;display:block;cursor:crosshair}
.plan .room{fill:var(--surface-2);stroke:var(--muted);stroke-width:1.5}
.plan .rl{fill:var(--muted);font-size:10px;font-family:var(--f-body)}
.plan .pin circle{stroke:var(--surface);stroke-width:2}
.plan .pin text{fill:#fff;font-size:9px;font-weight:700;font-family:var(--f-mono)}
.steps{display:flex;gap:0;direction:rtl;font-size:.72rem;flex-wrap:wrap}
.steps span{padding:3px 8px;background:var(--surface-2);color:var(--muted);border:1px solid var(--line);margin-inline-start:-1px}
.steps span.done{background:var(--accent-soft);color:var(--accent)}
.steps span.now{background:var(--accent);color:var(--accent-ink);border-color:var(--accent)}
.toast{position:fixed;bottom:calc(16px + env(safe-area-inset-bottom,0px));left:calc(16px + env(safe-area-inset-left,0px));z-index:50;background:var(--ink);color:var(--bg);padding:10px 14px;border-radius:6px;font-size:.85rem;max-width:min(420px,calc(100vw - 32px));box-shadow:0 6px 24px rgba(0,0,0,.2)}
.toast.crit{background:var(--crit);color:#fff}
.modal{position:fixed;inset:0;z-index:40;background:rgba(10,20,19,.55);display:grid;place-items:center;padding:16px}
.modal .box{background:var(--surface);border-radius:var(--r);max-width:900px;width:100%;max-height:calc(100vh - 32px);overflow:auto;padding:20px;display:grid;gap:14px}
.formal{border:1px solid var(--line);padding:22px;display:grid;gap:14px;background:var(--surface)}
.formal .lh{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;border-bottom:2px solid var(--ink);padding-bottom:10px}
.formal .lh div{font-size:.8rem}
.formal .sig{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin-top:24px}
.formal .sig div{border-top:1px solid var(--ink);padding-top:6px;font-size:.78rem;text-align:center}
@media (max-width:600px){.formal .sig{grid-template-columns:1fr}}
.offline{background:var(--warn-soft);color:var(--warn);padding:6px max(16px,env(safe-area-inset-right,0px)) 6px max(16px,env(safe-area-inset-left,0px));font-size:.82rem;border-bottom:1px solid var(--line)}
.wo{border:1px solid var(--line);border-radius:6px;padding:12px;display:grid;gap:8px;background:var(--surface)}
.wo label{display:flex;gap:8px;align-items:flex-start;font-size:.84rem}
.photos{display:flex;flex-wrap:wrap;gap:8px}
.photos img{width:120px;height:90px;object-fit:cover;border-radius:4px;border:1px solid var(--line)}
.denied{font-size:.78rem;color:var(--muted)}
.chips{display:flex;gap:6px;flex-wrap:wrap}
.chips button{border:1px solid var(--line);background:var(--surface);border-radius:99px;padding:3px 11px;font-size:.78rem;cursor:pointer}
.chips button[aria-pressed="true"]{background:var(--accent);color:var(--accent-ink);border-color:var(--accent)}
@media (max-width:900px){
  .app{grid-template-columns:minmax(0,1fr)}
  .side{position:static;height:auto;flex-direction:row;align-items:center;overflow-x:auto;padding-block:8px;padding-left:max(12px,env(safe-area-inset-left,0px));padding-right:max(12px,env(safe-area-inset-right,0px));border-inline-start:0;border-bottom:1px solid var(--line)}
  .brand,.side .foot{display:none}
  nav{display:flex;gap:4px}
  nav button{white-space:nowrap;padding:6px 9px}
  .top{position:static}
}
@media (prefers-reduced-motion: reduce){*{transition:none!important;animation:none!important}}


[hidden]{display:none!important}
.hm{border-collapse:separate;border-spacing:2px;font-size:.72rem}
.hm th{font-weight:500;color:var(--muted);padding:2px 4px;white-space:nowrap;text-align:start}
.hm th.v{writing-mode:vertical-rl;transform:rotate(180deg);height:150px;vertical-align:bottom;text-align:start;max-height:150px}
.hm td.c{width:22px;min-width:22px;height:20px;border-radius:3px;text-align:center;font-family:var(--f-mono);font-size:.62rem}
.hm td.l{white-space:nowrap;padding-inline-end:8px;font-family:var(--f-mono);font-size:.72rem}
.hm tr.g td{padding-top:10px;font-weight:600;color:var(--ink);font-family:var(--f-body);font-size:.78rem}
.empty{border:1px dashed var(--line);border-radius:var(--r);padding:28px 20px;display:grid;gap:8px;justify-items:start;background:var(--surface)}
.empty h3{color:var(--ink)}
.empty p{margin:0;color:var(--muted);max-width:62ch}
.en{display:block;color:var(--muted);font-size:.74rem;direction:ltr;text-align:right}
.lnk{display:inline-flex;gap:4px;align-items:center}
.lnk button{border:0;background:none;color:inherit;cursor:pointer;padding:0 2px;font-size:.9rem;line-height:1}
.src{font-size:.75rem;color:var(--muted)}
:root{--brand-teal:#157B98;--brand-gold:#CE902B}
.logo-plate{background:#fff;border-radius:8px;padding:8px 10px;display:block;line-height:0}
.logo-plate img{width:100%;height:auto;display:block}
.brandbar{height:6px;background:linear-gradient(to left,var(--brand-teal) 0 80%,transparent 80% 81%,var(--brand-gold) 81% 100%)}
.top-logo{display:none;width:120px}
@media (max-width:900px){.top-logo{display:block}}
.formal .lh .lg{width:170px;flex:none}
.formal .stripe-head{height:8px;margin:-22px -22px 0;background:linear-gradient(to left,var(--brand-teal) 0 80%,#fff 80% 81%,var(--brand-gold) 81% 100%)}
:root{--g-bar:#3f7fc4;--g-prog:#2f9e5b;--g-sum:#22313f;--g-band0:#d9e6f2;--g-band1:#e8f1e3;--g-rel:#5a6967;--g-head:#1f3a5a}
@media (prefers-color-scheme: dark){:root:not([data-theme="light"]){--g-bar:#5b9ad8;--g-prog:#4fbf7d;--g-sum:#c9d6e2;--g-band0:#1c2c3c;--g-band1:#1b2b20;--g-rel:#93a4a1;--g-head:#16283d}}
:root[data-theme="dark"]{--g-bar:#5b9ad8;--g-prog:#4fbf7d;--g-sum:#c9d6e2;--g-band0:#1c2c3c;--g-band1:#1b2b20;--g-rel:#93a4a1;--g-head:#16283d}
.gwrap{position:relative;overflow:auto;border:1px solid var(--line);border-radius:6px;max-height:70vh}
.gtab{border-collapse:collapse;font-size:.76rem;position:relative}
.gtab td,.gtab th{border-bottom:1px solid var(--line);border-right:1px solid var(--line);padding:0 6px;white-space:nowrap;background:var(--surface)}
.gtab thead th{position:sticky;top:0;z-index:4;background:var(--g-head);color:#fff;font-weight:500;height:40px;text-align:left}
.gtab td:nth-child(-n+8),.gtab th:nth-child(-n+8){position:sticky;z-index:3}
.gtab td:nth-child(1),.gtab th:nth-child(1){left:0;min-width:74px}
.gtab td:nth-child(2),.gtab th:nth-child(2){left:74px;min-width:220px;max-width:220px;overflow:hidden;text-overflow:ellipsis}
.gtab td:nth-child(3),.gtab th:nth-child(3){left:294px;min-width:46px}
.gtab td:nth-child(4),.gtab th:nth-child(4){left:340px;min-width:96px}
.gtab td:nth-child(5),.gtab th:nth-child(5){left:436px;min-width:96px}
.gtab td:nth-child(6),.gtab th:nth-child(6){left:532px;min-width:52px}
.gtab td:nth-child(7),.gtab th:nth-child(7){left:584px;min-width:46px}
.gtab td:nth-child(8),.gtab th:nth-child(8){left:630px;min-width:70px;border-right:2px solid var(--muted)}
.gtab thead th:nth-child(-n+8){z-index:5}
.gtab td.n{text-align:right;font-variant-numeric:tabular-nums}.gtab td.neg{color:var(--crit);font-weight:600}
.gtab tr.gb0 td{background:var(--g-band0);font-weight:700}.gtab tr.gb1 td{background:var(--g-band1);font-weight:600}
.gtab td.gt,.gtab th.gt{padding:0;position:relative;border-right:0}
.gtab td.gt{background:transparent}
.gtr{position:relative;height:25px}
.gscale{height:40px}.gmr,.gwr{position:relative;height:20px}
.gm,.gw{position:absolute;top:0;height:20px;border-left:1px solid rgba(255,255,255,.25);font-size:.68rem;padding-left:3px;overflow:hidden;line-height:20px}
.gwr .gw{color:rgba(255,255,255,.75)}
.gbar{position:absolute;top:7px;height:12px;background:var(--g-bar);border-radius:2px;overflow:hidden}
.gbar i{position:absolute;inset:0 auto 0 0;background:var(--g-prog)}
.gbar.crit{background:var(--crit)}.gbar.crit i{background:color-mix(in srgb,var(--g-prog) 80%,#000)}
.gbar.done{background:var(--g-prog)}
.gsum{position:absolute;top:9px;height:7px;background:var(--g-sum)}
.gsum::before,.gsum::after{content:"";position:absolute;bottom:-5px;border:5px solid transparent;border-top-color:var(--g-sum)}
