script:
const DATA=__PROJECT_DATA__;
const LOGO='';
document.documentElement.setAttribute('dir','rtl');document.documentElement.setAttribute('lang','ar');
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const nf=(n,d=0)=>Number(n||0).toLocaleString('en-US',{minimumFractionDigits:d,maximumFractionDigits:d});
const sar=n=>nf(n,2);
const pc=(f,d=2)=>nf((f||0)*100,d)+'%';
const MONTHS=['يناير','فبراير','مارس','أبريل','مايو','يونيو','يوليو','أغسطس','سبتمبر','أكتوبر','نوفمبر','ديسمبر'];
const TODAY=(()=>{try{const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}catch(e){return '2026-10-23'}})();
const days=(a,b)=>Math.round((new Date(b)-new Date(a))/864e5);
const isDate=s=>/^\d{4}-\d{2}-\d{2}$/.test(String(s||''));
const fdate=s=>{if(!isDate(s))return esc(s||'—');const d=new Date(s);return d.getDate()+' '+MONTHS[d.getMonth()]+' '+d.getFullYear()};
const OURCO={name:'شركة أراك الوطنية للتجارة والمقاولات',short:'أراك الوطنية',role:'مقاول باطن'};
const P=DATA.project, TY=DATA.types, IPC=DATA.ipcs[DATA.ipcs.length-1];
const TYK=Object.fromEntries(TY.map(t=>[t.k,t]));
const BUA_TOTAL=TY.reduce((s,t)=>s+t.bua*t.nb,0);
const SECS={build:'أعمال التشييد والبناء',equip:'التجهيزات والمعدات',ext:'الأعمال الخارجية'};
const FLOOR=f=>f==='GF'?'أرضي':f==='1st Floor'?'أول':f;

const ROLES={
  pm:{n:'مدير المشروع',p:['*']},
  qs:{n:'مهندس الكميات (QS)',p:['boq','ipc','link']},
  proc:{n:'مسؤول المشتريات',p:['po','link']},
  store:{n:'أمين المستودع',p:['grn','mir.issue']},
  site:{n:'مهندس الموقع',p:['mir.request','sched','wo']},
  sup:{n:'مشرف الموقع',p:['wo']},
  ceo:{n:'الرئيس التنفيذي',p:['*']},
  planner:{n:'مهندس التخطيط',p:['sched']},
  sub:{n:'مشرف مقاول الباطن',p:[]},
  cons:{n:'الاستشاري / مدقق المالك',p:[]},
};
const can=()=>false;
const dis=p=>can(p)?'':' disabled title="غير متاح لدور '+ROLES[S.role].n+'"';

/* ---------- state: real data is read-only from the Excel files; user actions live here ---------- */
const KEY='farasan-erp-v2';

function fresh(){return {v:2,role:'pm',online:true,outbox:[],view:'dash',audit:[],links:{},grns:[],mirs:[]}}
let S=fresh();
const SNAP=__PROJECT_SNAPSHOT__;
if(SNAP)S={...fresh(),...SNAP.s,view:'dash',online:true,outbox:[]};
let UI={wipT:'all',mpT:null,scSel:null,permTab:'roles',permUser:'',login:null,uEdit:null,tkSel:null,tkView:'board',tkMine:false,tkF:{},taskMine:false,gantt:false,gz:'week',siteTab:'wo',woSel:null,woF:'all',woB:'',tgtEdit:false,ipcNo:DATA.ipcs[DATA.ipcs.length-1].no,nb:null,nbQ:'',nbOpen:false,schEdit:false,unitSel:null,delArm:null,resetArm:null,boqSel:'3',boqSec:'all',boqQ:'',qty:0,ipc:'sum',ipcType:'D2',sched:'m3',procT:'all',store:'bal',stT:0};
function save(){}
function toast(m,k){const t=$('#toast');t.textContent=m;t.className='toast'+(k?' '+k:'');t.hidden=false;clearTimeout(toast.t);toast.t=setTimeout(()=>t.hidden=true,3800)}
function act(){toast('نسخة للاطلاع؛ التحديث عبر نسخة التقرير في المنصة.');return false}
function wipe(){}
/* ---------- editable schedule: Excel baseline + shared store (db), local fallback ---------- */
const clone=o=>JSON.parse(JSON.stringify(o));
const MS_ST={done:'منجز',progress:'قيد التنفيذ',late:'متأخر',pending:'لم يبدأ'};
const SCH0={
  m3:{project:DATA.schedule3.project,title:DATA.schedule3.title,due:DATA.schedule3.due,reportDate:DATA.schedule3.reportDate,manpower:DATA.schedule3.manpower,
      rows:DATA.schedule3.rows.map((r,i)=>({id:'r'+i,ar:r.ar,a:r.a,total:r.total,done:r.done,prog:r.prog,mat:r.mat,matDate:r.matDate,finish:r.finish,status:r.status,remark:r.remark}))},
  ms:{rows:[...IPC.milestones.map((m,i)=>({id:'m'+i,n:'المعلم '+(i+1),due:m.due,actual:'',state:m.state==='Milestone Passed'?'done':'late',note:m.status==='In Progress'?'قيد التنفيذ حسب المستخلص '+IPC.no:'منجز بعد تجاوز الموعد'})),
      {id:'mx',n:'الإنجاز المعدل للعقد',due:P.revisedCompletion,actual:'',state:'late',note:'لا يوجد تمديد زمني معتمد'}]},
  units:{p:{}},
  targets:{done:['T12'],T12:['D2-1','D2-2','D2-3','D2-4','D3-1','D3-2','D3-3','D3-4'],T3:['D2-5','D2-6','D3-5','D3-6','S2-1','S3-1'],T4:['D2-7','D2-8','D2-9','D2-10','D2-11','D3-7','D3-8','D3-9','D3-10','D3-11']}
};
SCH0.m4={project:DATA.schedule3.project,title:'حالة أعمال المستهدف الرابع – 10 مبانٍ (40 وحدة)',due:'',reportDate:'',manpower:'',fresh:true,
  rows:SCH0.m3.rows.map((r,i)=>({id:'q'+i,ar:r.ar,a:r.a,total:typeof r.total==='number'?40:r.total,done:'',prog:'',mat:'',matDate:'',finish:'',status:'',remark:''}))};
let SCH=clone(SCH0), SRC={m3:'excel',m4:'excel',ms:'excel',units:'excel',targets:'excel'}, DBH=null, STORE='local', RO=true;
if(S.sched)['m3','m4','ms','units','targets'].forEach(k=>{if(S.sched[k]){SCH[k]=clone(S.sched[k]);SRC[k]='local'}});
const canSch=()=>can('sched')&&!RO;
const pend={},busy={};
function persist(k){
  S.sched=S.sched||{};S.sched[k]=clone(SCH[k]);SRC[k]=DBH?'db':'local';save();
  if(!DBH)return;
  pend[k]=true;if(busy[k])return;busy[k]=true;
  (async()=>{while(pend[k]){pend[k]=false;
    try{await DBH.doc('schedule/'+k).set(clone(SCH[k]))}
    catch(e){if(e&&e.code==='unavailable'){await new Promise(r=>setTimeout(r,800+Math.random()*800));try{await DBH.doc('schedule/'+k).set(clone(SCH[k]))}catch(e2){toast('تعذر الحفظ في الخادم، حُفظ على هذا الجهاز','crit')}}
      else if(e&&e.code==='invalid_argument'){RO=true;toast('لا تملك صلاحية تعديل هذه الصفحة. اطلب صلاحية مساهم أو محرر.','crit');render()}
      else toast('تعذر الحفظ: '+((e&&e.message)||''),'crit');break}}
    busy[k]=false})();
}
const schAct=(k,label,fn)=>{if(!canSch()){toast(RO?'هذه الصفحة للقراءة فقط بالنسبة لك':'الدور الحالي لا يملك صلاحية تعديل الجدول الزمني','crit');return false}
  return act('sched',label,()=>{const r=fn();if(r===false)return false;persist(k)})};
const unitKey=u=>u.t+'|'+u.plot+'|'+u.u;
const unitP=u=>SCH.units.p[unitKey(u)]||u.p;
function actProgress(){ // official per-type progress + delta from edited unit grid
  const tw=Object.fromEntries(TY.map(t=>[t.k,IPC.cost.find(c=>typeAr(c.d)===t.ar).w]));
  return DATA.activities.map((a,i)=>{const per={};let ov=a.overall;
    TY.forEach(t=>{const us=DATA.unitProgress.filter(u=>u.t===t.k);const base=a.w&&tw[t.k]?(a.prog[t.k]||0)/(a.w*tw[t.k]):0;
      const d=us.reduce((s,u)=>s+(unitP(u)[i]-u.p[i]),0)/us.length;per[t.k]=Math.max(0,Math.min(1,base+d));ov+=a.w*tw[t.k]*(per[t.k]-base)});
    return {per,overall:ov}});
}
const overallNow=()=>actProgress().reduce((s,x)=>s+x.overall,0);
const unitsEdited=()=>Object.keys(SCH.units.p).length>0;

const auditList=()=>S.audit||[];function presenceNow(){}function paintPeers(){}function pushShared(){}function auditAdd(){}function liveRender(){render()}
/* ---------- derived ---------- */
const amt=(it,k)=>it.rate[k]*TYK[k].bua*TYK[k].nb;
const amtAll=it=>TY.reduce((s,t)=>s+amt(it,t.k),0);
const exAll=it=>TY.reduce((s,t)=>s+(it.exec[t.k]||0)+newExec(it.code,t.k),0);
const item=c=>DATA.boq.find(b=>b.code===c);
const links=i=>S.links[DATA.qtyTables[i].sheet]||DATA.qtyTables[i].boq;
const tablesFor=code=>DATA.qtyTables.map((t,i)=>({t,i})).filter(x=>links(x.i).includes(code));
const TOTKEY='اجمالي الاعداد', AVKEY='المتوفر', REQKEY='المطلوب';
const qnum=v=>typeof v==='number'?v:0;
function stock(ti,ri){const r=DATA.qtyTables[ti].rows[ri];const k=ti+'#'+ri;
  const g=S.grns.filter(x=>x.k===k).reduce((s,x)=>s+x.qty,0),m=S.mirs.filter(x=>x.k===k&&x.st==='issued').reduce((s,x)=>s+x.qty,0),req=S.mirs.filter(x=>x.k===k&&x.st==='requested').reduce((s,x)=>s+x.qty,0);
  return {alloc:qnum(r[TOTKEY]),open:qnum(r[AVKEY]),grn:g,issued:m,req,bal:qnum(r[AVKEY])+g-m};}
const UNITS_RAW=DATA.unitProgress.map(u=>({k:u.t+'|'+u.plot+'|'+u.u,bk:u.t+'-'+u.b,t:u.t,b:u.b,u:u.u,label:TYK[u.t].ar+' · '+u.plot+' · '+FLOOR(u.floor)+' · '+u.u}));
const unitsSorted=()=>UNITS_RAW.slice().sort((a,b)=>bTgtIdx(a.bk)-bTgtIdx(b.bk)||TY_IDX(a.t)-TY_IDX(b.t)||a.b-b.b||a.u-b.u);
const UNITS=UNITS_RAW;

/* ---------- shell ---------- */
const NAV=[['dash','لوحة','لوحة القيادة'],['tasks','مهام','إدارة المهام'],['boq','A','المقايسة'],['qty','A','جداول الكميات'],['ipc','A','مستخلصات المشروع'],['sched','D','الجدول الزمني'],['supply','B','جدول التوريدات'],['proc','B','المشتريات'],['store','B','المستودعات'],['labor','C','العمالة ومقاولو الباطن'],['site','E','الموقع وأوامر العمل'],['audit','سجل','سجل التدقيق'],['users','مستخدم','المستخدمون']];
function go(v){S.view=v;save();render();presenceNow();window.scrollTo(0,0);try{history.replaceState(null,'','#'+v)}catch(e){}}
function render(){
  if(SNAP&&S.view==='users')S.view='dash';
  if(S.view!=='users'&&modLv(S.view)<1){const f=NAV.find(n=>n[0]==='users'||modLv(n[0])>=1);S.view=f?f[0]:'users'}
  $('#nav').innerHTML=NAV.filter(n=>!(SNAP&&n[0]==='users')&&(n[0]==='users'||modLv(n[0])>=1)).map(([k,t,n])=>`<button onclick="go('${k}')" aria-current="${S.view===k}"><span class="tag">${t.length>2?t.slice(0,2):t}</span>${n}</button>`).join('');
  ['#sideLogo','#topLogo'].forEach(id=>{const e=$(id);if(e&&!e.src)e.src=LOGO});
  if(!CUR){$('#nav').innerHTML='';$('#userChip').innerHTML='';$('#view').innerHTML=vLogin();$('#ddLine').textContent='عقد '+P.contractNo;$('#netBtn').hidden=true;$('#syncBtn').hidden=true;$('#offBar').innerHTML='';const f=$('#lgNo');if(f&&f.focus&&!f.value)f.focus();return}
  if(!CUR.active){logout();return}S.role=CUR.role;$('#netBtn').hidden=false;$('#syncBtn').hidden=false;
  setTimeout(paintPeers,0);
  $('#userChip').innerHTML=SNAP?`<span class="pill warn">نسخة للاطلاع فقط</span>`:`<span class="pill acc" title="${esc(CUR.title||'')}">${esc(CUR.name)} · <span class="mono">${esc(CUR.no)}</span> · ${ROLES[CUR.role].n}</span> <button class="btn sm" onclick="exportSnap()" title="ملف HTML واحد يحمل كل البيانات الحالية ويفتح بدون إنترنت أو حساب">تصدير نسخة كاملة</button> <button class="btn sm" onclick="go('users')">حسابي</button> <button class="btn sm" onclick="logout()">خروج</button>`;
  $('#ddLine').textContent='عقد '+P.contractNo+' · '+TY.reduce((s,t)=>s+t.nb,0)+' مبنى · '+TY.reduce((s,t)=>s+t.units,0)+' وحدة سكنية · آخر مستخلص: رقم '+IPC.no+' حتى '+fdate(IPC.to).replace(/<[^>]+>/g,'');
  $('#srcFoot').textContent='المصدر: ملفات Excel المرفقة (المستخلص 16، المقايسة، جداول الكميات، المستهدف الثالث).';
  $('#netBtn').innerHTML=S.online?'<span class="pill ok">متصل</span>':'<span class="pill warn">دون اتصال</span>';
  $('#syncBtn').textContent=S.outbox.length?'مزامنة ('+S.outbox.length+')':'مزامنة';
  $('#offBar').innerHTML=S.online?'':`<div class="offline">العمل دون اتصال: تُحفظ الحركات على الجهاز (${S.outbox.length} بانتظار المزامنة).</div>`;
