/* ---------- quantity tables by building & target ---------- */
const TGT={T12:'المستهدف الأول والثاني',T3:'المستهدف الثالث',T4:'المستهدف الرابع'};
const bTarget=bk=>Object.keys(TGT).find(t=>(SCH.targets[t]||[]).includes(bk))||'';
const typeOK=(mt,t)=>mt==='all'||(mt==='2'&&(t==='D2'||t==='S2'))||(mt==='3'&&(t==='D3'||t==='S3'));
const bFactor=b=>b.units.length/4;
function qSel(){if(!S.qSel)S.qSel=[...(SCH.targets.T4||[])];return S.qSel.filter(k=>BLDK[k])}
function qtyFor(t,row,sel){if(t.custom||t.simple)return sel.reduce((a,bk)=>{const b=BLDK[bk];return a+(b?(+(row.q||{})[b.t]||0):0)},0);return t.model.reduce((s,m)=>{const q=qnum(row[m.q]);if(!q)return s;return s+q*sel.reduce((x,bk)=>{const b=BLDK[bk];return x+(typeOK(m.t,b.t)?bFactor(b):0)},0)},0)}
function setQSel(arr){S.qSel=arr;save();render()}
function qPick(t){setQSel(t==='all'?BLD.map(b=>b.k):[...(SCH.targets[t]||[])])}
function qToggle(bk){const s=qSel();setQSel(s.includes(bk)?s.filter(x=>x!==bk):[...s,bk])}
function qType(tk,on){const s=qSel().filter(k=>BLDK[k].t!==tk);setQSel(on?[...s,...BLD.filter(b=>b.t===tk).map(b=>b.k)]:s)}

/* buildings always ordered by target (1-2, 3, 4, unassigned), then type, then sequence */
const TGT_ORD=['T12','T3','T4'];
const TY_IDX=k=>TY.findIndex(t=>t.k===k);
const bTgtIdx=bk=>{const i=TGT_ORD.indexOf(bTarget(bk));return i<0?9:i};
const bSorted=()=>BLD.slice().sort((a,b)=>bTgtIdx(a.k)-bTgtIdx(b.k)||TY_IDX(a.t)-TY_IDX(b.t)||a.b-b.b);
const bGroups=()=>{const g=[];bSorted().forEach(b=>{const t=bTarget(b.k)||'';let x=g.find(y=>y.t===t);if(!x)g.push(x={t,n:TGT[t]||'بدون مستهدف',bs:[]});x.bs.push(b)});return g};
const TYS={D2:'دوبلكس غرفتين',D3:'دوبلكس 3 غرف',S2:'مشترك غرفتين',S3:'مشترك 3 غرف'};
const bChip=b=>`<span class="mono" dir="ltr">${esc(b.plot)}</span> <span class="src" style="font-size:.68rem">${TYS[b.t]}</span>`;
const bOpts=(sel)=>bGroups().map(g=>`<optgroup label="${g.n}">${g.bs.map(b=>`<option value="${b.k}"${sel===b.k?' selected':''}>${esc(b.plot)} · ${TYS[b.t]}</option>`).join('')}</optgroup>`).join('');
function qGroup(t,on){const ks=bGroups().find(g=>g.t===t).bs.map(b=>b.k);const s=qSel().filter(k=>!ks.includes(k));setQSel(on?[...s,...ks]:s)}
function setTarget(bk,t){const cur=bTarget(bk);if(cur===t)return;const b=BLDK[bk];
  schAct('targets','توزيع المستهدفات · مبنى '+b.plot+': '+(TGT[t]||'بدون مستهدف'),()=>{for(const k in TGT)SCH.targets[k]=(SCH.targets[k]||[]).filter(x=>x!==bk);if(t)SCH.targets[t].push(bk)})}
const fmtQ=v=>nf(v,Math.abs(v%1)>1e-9?2:0);
/* ---------- custom quantity tables (added in the page, quantities per building type) ---------- */
const QT_STATIC=DATA.qtyTables.length;
let CQT=S.cqt?clone(S.cqt):{tables:[]};
const canCq=()=>can('link')&&!RO;
function cqBuild(){DATA.qtyTables.length=QT_STATIC;CQT.tables.forEach(ct=>{
  const rows=ct.rows.map(r=>{const tot=BLD.reduce((s,b)=>s+(+(r.q||{})[b.t]||0),0),av=+r.av||0;return {...r,n:r.n,item:r.item,desc:'',price:r.price,[TOTKEY]:tot,[AVKEY]:av,[REQKEY]:Math.max(0,tot-av)}});
  DATA.qtyTables.push({custom:true,id:ct.id,sheet:ct.sheet,title:ct.title,target:'كل المباني',cols:[],model:[],boq:ct.boq||[],rows})})}
const cqSave=()=>{S.cqt=clone(CQT);save();saveDoc('lists','cqty',()=>CQT)};
const cqById=id=>CQT.tables.find(t=>t.id===id);
function cqAct(label,fn){if(!canCq()){toast(RO?'هذه الصفحة للقراءة فقط بالنسبة لك':'لا تملك صلاحية تعديل جداول الكميات','crit');return false}
  return act(null,'جداول الكميات · '+label,()=>{const r=fn();if(r===false)return false;cqBuild();cqSave()})}
function cqNewTable(){const n=CQT.tables.reduce((m,t)=>Math.max(m,+String(t.id).replace(/\D/g,'')||0),0)+1,id='CQ-'+n;
  if(cqAct('إنشاء جدول جديد',()=>{CQT.tables.push({id,sheet:'جدول جديد '+n,title:'',boq:[],rows:[]})}))UI.qty=DATA.qtyTables.findIndex(t=>t.id===id),render()}
function cqSet(id,f,v){const t=cqById(id);const val=String(v).trim();if(f==='sheet'&&!val){toast('اسم الجدول مطلوب','crit');render();return}
  if(f==='sheet'&&DATA.qtyTables.some(x=>x.sheet===val&&x.id!==id)){toast('يوجد جدول بنفس الاسم','crit');render();return}if(String(t[f]??'')===val)return;
  const old=t.sheet;cqAct((f==='sheet'?'اسم الجدول':'العنوان')+': '+val,()=>{t[f]=val;if(f==='sheet'&&S.links[old]){S.links[val]=S.links[old];delete S.links[old]}})}
function cqAddRow(id){const t=cqById(id);const n=t.rows.reduce((m,r)=>Math.max(m,+r.n||0),0)+1;cqAct(t.sheet+' · إضافة صنف',()=>{t.rows.push({id:'r'+Date.now().toString(36),n,item:'صنف جديد',unit:'',q:{D2:'',D3:'',S2:'',S3:''},price:'',av:0})})}
function cqRow(id,rid,f,v){const t=cqById(id),r=t.rows.find(x=>x.id===rid);if(!r)return;let val=v;
  if(f.startsWith('q.')){const k=f.slice(2);val=v===''?'':Math.max(0,+v||0);if(String(r.q[k]??'')===String(val))return;return cqAct(t.sheet+' · '+r.item+' · كمية '+TYS[k]+' للمبنى: '+(val===''?'—':val),()=>{r.q[k]=val})}
  if(f==='price'||f==='av'){val=v===''?'':Math.max(0,+v||0)}else val=String(v).trim();
  if(f==='item'&&!val){toast('اسم الصنف مطلوب','crit');render();return}if(String(r[f]??'')===String(val))return;
  cqAct(t.sheet+' · '+r.item+' · '+{item:'الصنف',unit:'الوحدة',price:'سعر الوحدة',av:'المتوفر'}[f]+': '+(val===''?'—':val),()=>{r[f]=val})}
function cqDelRow(id,rid){const t=cqById(id),r=t.rows.find(x=>x.id===rid);UI.delArm=null;
  const i=DATA.qtyTables.findIndex(x=>x.id===id),j=t.rows.indexOf(r);
  if(WOS.some(w=>(w.mats||[]).some(m=>m.src&&m.src.i===i&&m.src.j===j))||S.grns.some(g=>g.k===i+'#'+j)||S.mirs.some(g=>g.k===i+'#'+j)){toast('لا يمكن حذف صنف مستخدم في أوامر العمل أو حركات المستودع','crit');return}
  if(j!==t.rows.length-1&&WOS.some(w=>(w.mats||[]).some(m=>m.src&&m.src.i===i))){toast('احذف الأصناف من آخر الجدول فقط لأن الجدول مستخدم في أوامر العمل','crit');return}
  cqAct(t.sheet+' · حذف صنف: '+r.item,()=>{t.rows=t.rows.filter(x=>x.id!==rid)})}
function vQtyCustom(i,t,sel){const ct=cqById(t.id),ed=canCq();
  const rows=t.rows.map((r,j)=>{const src=ct.rows[j],q=qtyFor(t,r,sel),p=priceOf(i,j);return {r,src,j,q,p,av:qnum(r[AVKEY])}});
  const qi=(r,k)=>ed?`<input data-edit type="number" min="0" step="any" value="${esc(r.q[k]??'')}" placeholder="—" style="width:76px" onchange="cqRow('${ct.id}','${r.id}','q.${k}',this.value)">`:(r.q[k]!==''&&r.q[k]!=null?fmtQ(+r.q[k]):'—');
  const tx=(r,f,w)=>ed?`<input data-edit type="text" value="${esc(r[f]??'')}" style="width:${w}" onchange="cqRow('${ct.id}','${r.id}','${f}',this.value)">`:esc(r[f]||'—');
  return `<section class="card"><header><div><h3>${ed?`<input data-edit type="text" value="${esc(ct.sheet)}" onchange="cqSet('${ct.id}','sheet',this.value)" style="font-weight:600;min-width:240px">`:esc(ct.sheet)}</h3><span class="src">جدول مضاف في النظام · ${ct.rows.length} صنفاً · الكمية تُدخل لكل مبنى حسب نوعه وتُجمع للمباني المحددة</span></div>${ed?`<button class="btn pri" onclick="cqAddRow('${ct.id}')">+ إضافة صنف</button>`:''}</header>
   ${tLinks(i)}
   <div class="grid g4"><div class="kpi"><span class="lb">قيمة الأصناف للمحدد</span><span class="v">${sar(rows.reduce((s,x)=>s+(x.p!==''?x.q*x.p:0),0))}</span><span class="s">${sel.length} مبنى</span></div>
    ${rows.slice(0,3).map(x=>`<div class="kpi"><span class="lb">${esc(x.r.item)}</span><span class="v">${fmtQ(x.q)}<small> ${esc(x.r.unit||'')}</small></span><span class="s">للمباني المحددة</span></div>`).join('')}</div></section>
  ${sel.length?'':`<div class="check bad">لم يُحدد أي مبنى. اختر مستهدفاً أو مبنى واحداً على الأقل.</div>`}
  ${rows.length?`<div class="tw"><table class="d" id="tQty"><thead><tr><th>م</th><th>الصنف</th><th>الوحدة</th>${TY.map(ty=>`<th class="n">${TYS[ty.k]} / مبنى</th>`).join('')}<th class="n">الكمية للمحدد</th><th class="n">سعر الوحدة</th><th class="n">القيمة للمحدد</th><th class="n">المتوفر</th><th class="n">المطلوب للمحدد</th><th class="n">إجمالي كل المباني</th>${ed?'<th></th>':''}</tr></thead><tbody>
   ${rows.map(({r,src,j,q,p,av})=>`<tr data-edit><td class="mono">${r.n}</td><td>${tx(src,'item','100%;min-width:150px')}</td><td>${tx(src,'unit','64px')}</td>${TY.map(ty=>`<td class="n">${qi(src,ty.k)}</td>`).join('')}
    <td class="n" style="font-weight:600">${q?fmtQ(q):'—'}</td><td class="n">${canPrice()?`<input data-edit type="number" min="0" step="any" value="${p}" placeholder="—" style="width:80px" onchange="setPrice(${i},${j},this.value)">`:(p!==''?sar(p):'—')}</td><td class="n">${p!==''&&q?sar(q*p):''}</td>
    <td class="n">${ed?`<input data-edit type="number" min="0" step="any" value="${esc(src.av??'')}" style="width:70px" onchange="cqRow('${ct.id}','${src.id}','av',this.value)">`:fmtQ(av)}</td><td class="n" style="${Math.max(0,q-av)>0?'font-weight:600;color:var(--accent)':''}">${Math.max(0,q-av)?fmtQ(Math.max(0,q-av)):'—'}</td><td class="n muted">${fmtQ(qnum(r[TOTKEY]))}</td>
