const BLD=(()=>{const m={};DATA.unitProgress.forEach(u=>{const k=u.t+'-'+u.b;(m[k]=m[k]||{k,t:u.t,b:u.b,plot:u.plot,units:[]}).units.push(u)});return Object.values(m)})();
