const bval=(code,t)=>{const it=item(code);return it?it.rate[t]*TYK[t].bua:0};
/* previous certified value per building & item: IPC 16 type totals distributed by unit progress, balanced so that
   building totals = official per-unit values and item totals = official per-type values */
const PREV0=(()=>{const out={};
  const gp=(units,it)=>{let s=0,tot=0;const mean=j=>units.reduce((x,u)=>x+u.p[j],0)/units.length;
    it.subs.forEach(sb=>{const a=sb.act,main=a>=1&&a<=20?mean(a-1):0,ext=(mean(17)+mean(18)+mean(19))/3;s+=sb.share*((1-sb.k)*main+sb.k*ext);tot+=sb.share});return tot?s/tot:0};
  TY.forEach(t=>{const bs=BLD.filter(b=>b.t===t.k).sort((a,b)=>a.b-b.b),items=DATA.boq.filter(it=>it.rate[t.k]>0);
    const U=IPC.units[t.k]||[],rowT=bs.map((b,i)=>U.slice(i*t.upb,(i+1)*t.upb).reduce((s,x)=>s+x.cum,0));
    const M=bs.map(b=>Object.fromEntries(items.map(it=>[it.code,Math.max(1e-6,gp(b.units,it))*it.rate[t.k]*t.bua])));
    for(let n=0;n<200;n++){
      M.forEach((r,i)=>{const s=Object.values(r).reduce((a,b)=>a+b,0),f=s?rowT[i]/s:0;for(const c in r)r[c]*=f});
      items.forEach(it=>{const s=M.reduce((a,r)=>a+r[it.code],0),f=s?it.exec[t.k]/s:0;M.forEach(r=>r[it.code]*=f)});
      M.forEach(r=>{for(const c in r)r[c]=Math.min(r[c],bval(c,t.k))});
    }
    bs.forEach((b,i)=>{out[b.k]=M[i]});
  });return out})();
