function prevPct(bk,code,beforeNo){const b=BLDK[bk],v=bval(code,b.t);if(!v)return 0;
  const base=((PREV0[bk]||{})[code]||0)/v*100;
  return base+NIPC.filter(x=>x.no<beforeNo).flatMap(x=>x.lines).filter(l=>l.b===bk&&l.code===code).reduce((s,l)=>s+(+l.pct||0),0)}
function newExec(code,k){return NIPC.filter(x=>x.status==='submitted').flatMap(x=>x.lines).filter(l=>l.code===code&&BLDK[l.b]&&BLDK[l.b].t===k).reduce((s,l)=>s+lineVal(l),0)}
function bldCum(bk,beforeNo){const b=BLDK[bk];let v=0,tot=0;DATA.boq.forEach(it=>{const x=bval(it.code,b.t);if(!x)return;tot+=x;v+=prevPct(bk,it.code,beforeNo)/100*x});return tot?v/tot:0}
function ipcCalcNew(d){
  const cur=linesVal(d),r=(+d.ret||0)/100,v=(+d.vat||0)/100;
  const C={main:cur,vo:0,total:cur,vat:cur*v,totalVat:cur*(1+v),retention:cur*r,ld:+d.ld||0,otherDed:+d.other||0};
  C.totalDed=C.retention+C.ld+C.otherDed;C.net=C.totalVat-C.totalDed;
  const L=IPC.lines,P={main:L.main[2],vo:L.vo[2],total:L.total[2],vat:L.vat[2],totalVat:L.totalVat[2],retention:L.retention[2],ld:L.ld[2],otherDed:L.otherDed[2],totalDed:-L.totalDed[2],net:L.net[2]};
  NIPC.filter(x=>x.no<d.no).forEach(x=>{const c=ipcCalcNew.cur(x);for(const k in P)P[k]+=c[k]});
