}
ipcCalcNew.cur=d=>{const cur=linesVal(d),r=(+d.ret||0)/100,v=(+d.vat||0)/100;const C={main:cur,vo:0,total:cur,vat:cur*v,totalVat:cur*(1+v),retention:cur*r,ld:+d.ld||0,otherDed:+d.other||0};C.totalDed=C.retention+C.ld+C.otherDed;C.net=C.totalVat-C.totalDed;return C};
