  schAct(K,(K==='m3'?'المستهدف الثالث':'المستهدف الرابع')+' · جدولة حسب العلاقات: نُقل '+changes.length+' نشاط',()=>{changes.forEach(x=>{const r=M.rows[x.i];r.start=S2[x.id].s;r.finish=S2[x.id].f})})}
