function catSet(gi,ii,v){if(!canPrice()){toast('لا تملك صلاحية تعديل الأسعار','crit');return}const k=gi+'.'+ii,x=CAT[gi].items[ii],val=v===''?'':Math.max(0,+v||0);if(String(catPrice(gi,ii))===String(val===''?(x.lo??''):val))return;
  if(act(null,'سعر الصنف «'+x.item+'»: '+(val===''?'حسب أقل سعر':sar(val)),()=>{if(val===''||val===x.lo)delete CATP.p[k];else CATP.p[k]=val;S.catp=clone(CATP)}))saveDoc('lists','catprice',()=>CATP)}
function vCatalog(){const ci=UI.catG==null?'all':UI.catG,q=(UI.catQ||'').trim(),ed=canPrice();
