function woCatAdd(no){const w=woById(no);if(!w||!woEditable(w))return;const v=($('#cpI')||{}).value,q=+(($('#cpQ')||{}).value)||0;if(!v){toast('اختر الصنف','crit');return}if(q<=0){toast('أدخل الكمية','crit');return}
