const POST={requested:['طلب شراء','info'],ordered:['أُرسل للمورد','acc'],shipped:['في الطريق','acc'],delivered:['تم التوريد','ok'],cancelled:['ملغي','crit']};
let POS=S.pos?clone(S.pos):[];
const poById=id=>POS.find(p=>p.id===id);
const poSub=p=>(p.lines||[]).reduce((s,l)=>s+(+l.qty||0)*(+l.price||0),0);
const poVat=p=>poSub(p)*(+p.vat||0)/100;
const poSave=p=>{S.pos=clone(POS);save();saveDoc('po',p.id,()=>poById(p.id))};
const canPo=()=>can('po')&&!RO;
const poEd=p=>canPo()&&['requested','ordered'].includes(p.status);
const poNorm=s=>String(s||'').trim().toLowerCase().replace(/\s+/g,'');
const poSupRows=p=>p.no?supAll().filter(x=>poNorm(x.po)===poNorm(p.no)):[];
function poAct(p,label,fn){if(!canPo()){toast(RO?'هذه الصفحة للقراءة فقط بالنسبة لك':'لا تملك صلاحية أوامر الشراء','crit');return false}return act('po',(p.no||p.id)+' · '+label,()=>{const r=fn();if(r===false)return false;poSave(p)})}
function newPo(){const n=POS.reduce((m,p)=>{const x=/^PR-(\d+)$/.exec(p.id);return x?Math.max(m,+x[1]):m},0)+1,id='PR-'+String(n).padStart(4,'0');
  const p={id,no:id,date:TODAY,sup:'',tgt:'',wo:'',vat:15,lines:[{item:'',unit:'',qty:'',price:'',boq:''}],terms:'',note:'',status:'requested',by:CUR?CUR.name:''};
  if(poAct(p,'إنشاء طلب شراء',()=>{POS.unshift(p)})){UI.poSel=id;render()}}
function poSet(id,f,v){const p=poById(id);if(!p||!poEd(p))return;const val=f==='vat'?(v===''?0:Math.max(0,+v||0)):(typeof v==='string'?v.trim():v);if(String(p[f]??'')===String(val))return;
  if(f==='no'&&!val){toast('رقم الطلب مطلوب','crit');render();return}
  const lbl={no:'الرقم',date:'التاريخ',sup:'المورد',tgt:'المستهدف',wo:'أمر العمل',vat:'نسبة الضريبة',terms:'الشروط',note:'ملاحظات'}[f];
  poAct(p,lbl+': '+(f==='tgt'?(TGT[val]||'—'):val===''?'—':String(val).slice(0,60)),()=>{p[f]=val})}
function poLine(id,i,f,v){const p=poById(id);if(!p||!poEd(p))return;const l=p.lines[i];if(!l)return;const num=['qty','price'].includes(f);const val=num?(v===''?'':Math.max(0,+v||0)):String(v).trim();if(String(l[f]??'')===String(val))return;
  poAct(p,'سطر '+(i+1)+': '+val,()=>{l[f]=val})}
function poAddL(id){const p=poById(id);if(!p||!poEd(p))return;poAct(p,'إضافة صنف',()=>{p.lines.push({item:'',unit:'',qty:'',price:'',boq:''})})}
function poDelL(id,i){const p=poById(id);if(!p||!poEd(p))return;poAct(p,'حذف سطر '+(i+1),()=>{p.lines.splice(i,1)})}
function poStatus(id,st){const p=poById(id);if(!p||!canPo()||p.status===st)return;
  const rows=poSupRows(p);
  poAct(p,'الحالة: '+POST[st][0]+(rows.length&&st!=='cancelled'?' · تحديث '+rows.length+' سطر في جدول التوريدات':''),()=>{p.status=st;
    if(st!=='cancelled'&&rows.length){rows.forEach(x=>{const o=x.manual?SUP.manual.find(m=>'x:'+m.id===x.key):(SUP.rows[x.key]=SUP.rows[x.key]||{});if(o)o.st=st});supSave()}})}
function poDel(id){const p=poById(id);UI.delArm=null;if(!p||!canPo())return;if(!['requested','cancelled'].includes(p.status)){toast('يمكن حذف طلبات الشراء غير المرسلة أو الملغاة فقط','crit');return}
  if(act('po','حذف طلب الشراء '+(p.no||p.id),()=>{POS=POS.filter(x=>x.id!==id);UI.poSel=null;S.pos=clone(POS)}))saveDoc('po',id,null,true)}
