  woAct('wo',w,'إضافة مواد البند '+w.boq+' من جداول الكميات',()=>{w.mats=w.mats||[];T.forEach(({t,i})=>t.rows.forEach((r,j)=>{if(r.boq&&r.boq!==w.boq)return;if(w.mats.some(m=>m.src&&m.src.i===i&&m.src.j===j))return;const q=Math.round(qtyFor(t,r,w.bldgs)*100)/100;if(q>0){w.mats.push({name:r.item,unit:r.unit||'',qty:q,price:priceOf(i,j),src:{i,j,sheet:t.sheet}});n++}}));if(!n){toast('لا توجد كميات لهذه المباني','crit');return false}})}
