/* ---------- work orders, signatures & building cost ---------- */
const TRADES=['مراقب عمال','بنّاء','حدّاد مسلح','نجّار مسلح','لياس','مبلّط','دهّان','كهربائي','سبّاك','عامل عادي','مشغّل معدات'];
const WOST={draft:['مسودة',''],sup:['بانتظار الاعتماد','warn'],pm:['بانتظار الاعتماد','warn'],approved:['معتمد','ok'],closed:['منفذ ومغلق','acc']};
let WOS=S.wos?clone(S.wos):[], CONTR=S.contr?clone(S.contr):{list:[]}, RATES=S.rates?clone(S.rates):{r:{}};
const dB={},dP={};
function saveDoc(coll,id,getter,del){
  S.wos=clone(WOS);S.contr=clone(CONTR);S.rates=clone(RATES);save();if(!DBH)return;const key=coll+'/'+id;
  if(del){DBH.doc(key).delete().catch(()=>toast('تعذر الحذف من الخادم','crit'));return}
  dP[key]=true;if(dB[key])return;dB[key]=true;
  (async()=>{while(dP[key]){dP[key]=false;const v=getter();if(!v)break;
    try{await DBH.doc(key).set(clone(v))}catch(e){if(e&&e.code==='invalid_argument'){RO=true;toast('لا تملك صلاحية الحفظ على هذه الصفحة','crit')}else toast('تعذر الحفظ في الخادم، حُفظ على هذا الجهاز','crit');break}}
    dB[key]=false})();
}
const woById=no=>WOS.find(w=>w.no===no);
