const woAct=(perm,w,label,fn)=>{if(RO){toast('هذه الصفحة للقراءة فقط بالنسبة لك','crit');return false}return act(perm,w.no+' · '+label,()=>{const r=fn();if(r===false)return false;woSave(w)})};
const woCost=w=>(w.mode==='sub'?(+w.value||0):labSum(w))+matSum(w)+eqSum(w);
const woParts=w=>({labor:w.mode==='sub'?0:labSum(w),mats:matSum(w),equip:eqSum(w),sub:w.mode==='sub'?(+w.value||0):0});
function woAlloc(w){const bs=(w.bldgs||[]).filter(k=>BLDK[k]),u=bs.reduce((s,k)=>s+BLDK[k].units.length,0);return bs.map(k=>({k,share:u?BLDK[k].units.length/u:0}))}
const bContract=bk=>{const b=BLDK[bk];return DATA.boq.reduce((s,it)=>s+bval(it.code,b.t),0)};
const plots=w=>(w.bldgs||[]).filter(k=>BLDK[k]).map(k=>BLDK[k].plot);
const woEditable=w=>w.status==='draft'&&can('wo')&&!RO;

function newWo(){const n=WOS.reduce((m,w)=>Math.max(m,+String(w.no).replace(/\D/g,'')||0),0)+1,no='WO-'+String(n).padStart(4,'0');
  const w={no,date:TODAY,title:'',desc:'',boq:'',bldgs:[],mode:'own',contractor:'',value:'',start:TODAY,end:'',labor:[{trade:'عامل عادي',n:1,days:1,rate:RATES.r['عامل عادي']||''}],mats:[],equip:[],status:'draft',sigs:{},by:CUR?CUR.name:ROLES[S.role].n,note:''};
  if(woAct('wo',w,'إنشاء أمر عمل',()=>{WOS.unshift(w)})){UI.woSel=no;render()}}
function woSet(no,f,v){const w=woById(no);if(!w||!woEditable(w))return;const num=['value'].includes(f);const val=num?(v===''?'':Math.max(0,+v||0)):v;if(String(w[f]??'')===String(val))return;
  const lbl={title:'الوصف المختصر',desc:'التفاصيل',boq:'بند المقايسة',mode:'جهة التنفيذ',contractor:'المقاول',value:'قيمة أمر العمل',start:'البداية',end:'النهاية',date:'التاريخ',note:'ملاحظات'}[f];
  woAct('wo',w,lbl+': '+(f==='mode'?(val==='sub'?'مقاول باطن':'عمالة الشركة'):val===''?'—':val),()=>{w[f]=val})}
function woB(no,bk){const w=woById(no);if(!w||!woEditable(w))return;const has=w.bldgs.includes(bk);woAct('wo',w,(has?'إزالة':'إضافة')+' المبنى '+BLDK[bk].plot,()=>{w.bldgs=has?w.bldgs.filter(x=>x!==bk):[...w.bldgs,bk]})}
function woBT(no,t){const w=woById(no);if(!w||!woEditable(w))return;woAct('wo',w,'تحديد مباني '+(TGT[t]||t),()=>{w.bldgs=[...(SCH.targets[t]||[])]})}
const LK={labor:['trade','n','days','rate'],mats:['name','unit','qty','price'],equip:['name','hours','rate']};
function woLine(no,kind,i,f,v){const w=woById(no);if(!w||!woEditable(w))return;const l=w[kind][i];if(!l)return;const num=!['trade','name','unit'].includes(f);const val=num?(v===''?'':Math.max(0,+v||0)):v;if(String(l[f]??'')===String(val))return;
  woAct('wo',w,{labor:'العمالة',mats:'المواد',equip:'المعدات'}[kind]+' · سطر '+(i+1)+': '+val,()=>{l[f]=val;if(kind==='labor'&&f==='trade'&&RATES.r[val]&&!l.rate)l.rate=RATES.r[val]})}
function woAdd(no,kind){const w=woById(no);if(!w||!woEditable(w))return;woAct('wo',w,'إضافة سطر '+{labor:'عمالة',mats:'مواد',equip:'معدات'}[kind],()=>{w[kind]=w[kind]||[];w[kind].push(kind==='labor'?{trade:'عامل عادي',n:1,days:1,rate:RATES.r['عامل عادي']||''}:kind==='mats'?{name:'',unit:'',qty:'',price:''}:{name:'',hours:'',rate:''})})}
function woDelL(no,kind,i){const w=woById(no);if(!w||!woEditable(w))return;woAct('wo',w,'حذف سطر '+{labor:'عمالة',mats:'مواد',equip:'معدات'}[kind],()=>{w[kind].splice(i,1)})}
function woCheck(w){return !w.title?'أدخل وصف العمل':!w.bldgs.length?'اختر مبنى واحداً على الأقل':w.mode==='sub'&&!w.contractor?'اختر المقاول':w.mode==='sub'&&!(+w.value>0)?'أدخل قيمة أعمال المصنعيات':w.mode==='own'&&!(woCost(w)>0)?'أدخل تكلفة المصنعيات أو المواد':''}
function woSend(no){const w=woById(no);if(!w)return;const err=woCheck(w);if(err){toast(err,'crit');return}woAct('wo',w,'إرسال للاعتماد',()=>{w.status='pm';w.rej=''})}
function woApprove(no){const w=woById(no);if(!w)return;if(!can('sign.pm')){toast('لا تملك صلاحية اعتماد أوامر العمل','crit');return}const err=woCheck(w);if(err){toast(err,'crit');return}
  woAct(null,w,'اعتماد أمر العمل · '+sar(woCost(w))+' ر.س',()=>{w.status='approved';w.rej='';w.appr={name:CUR?CUR.name:'',no:CUR?CUR.no:'',at:new Date().toISOString()};delete w.sigs})}
function woReject(no){const w=woById(no),note=($('#rejNote')||{}).value||'';if(!w)return;if(!can('sign.pm')){toast('الرفض لصاحب صلاحية الاعتماد فقط','crit');return}
  woAct(null,w,'رفض وإعادة إلى مسودة'+(note?': '+note:''),()=>{w.status='draft';delete w.appr;delete w.sigs;w.rej=note||'أعيد للتعديل'})}
function woUnapprove(no){const w=woById(no);if(!w||!can('sign.pm'))return;UI.delArm=null;if(w.status!=='approved'){toast('يمكن إلغاء الاعتماد للأوامر المعتمدة غير المغلقة فقط','crit');return}woAct(null,w,'إلغاء الاعتماد وإعادة إلى مسودة',()=>{w.status='draft';delete w.appr})}
function woClose(no){const w=woById(no);if(!w)return;if(!(can('wo')||can('sign.pm'))){toast('غير مسموح لهذا المستخدم','crit');return}if(w.boq&&!(+w.billPct>0)){toast('حدد نسبة إنجاز البند قبل الإغلاق ليصبح قابلاً للفوترة','crit');return}woAct(null,w,'إغلاق: تم التنفيذ'+(w.boq?' · قابل للفوترة '+sar(woPlanned(w))+' ر.س':''),()=>{w.status='closed';w.closed=TODAY})}
function woDel(no){const w=woById(no);UI.delArm=null;if(!w||w.status!=='draft'){toast('يمكن حذف المسودات فقط','crit');return}
  if(act('wo','حذف أمر العمل '+no,()=>{WOS=WOS.filter(x=>x.no!==no);UI.woSel=null}))saveDoc('workorders',no,null,true)}
function contrAdd(){const n=($('#cName').value||'').trim(),sc=($('#cScope').value||'').trim();if(!n){toast('اكتب اسم المقاول','crit');return}if(CONTR.list.some(c=>c.name===n)){toast('المقاول موجود','crit');return}
  if(act('wo','إضافة مقاول: '+n,()=>{CONTR.list.push({name:n,scope:sc})}))saveDoc('lists','contractors',()=>CONTR)}
function contrDel(n){UI.delArm=null;if(WOS.some(w=>w.contractor===n)){toast('لا يمكن حذف مقاول له أوامر عمل','crit');return}if(act('wo','حذف مقاول: '+n,()=>{CONTR.list=CONTR.list.filter(c=>c.name!==n)}))saveDoc('lists','contractors',()=>CONTR)}
function rateSet(t,v){const val=v===''?'':Math.max(0,+v||0);if(String(RATES.r[t]??'')===String(val))return;if(act('rates','أجر يومي '+t+': '+(val===''?'—':val),()=>{RATES.r[t]=val}))saveDoc('lists','rates',()=>RATES)}

function bldChips(w,ed){return bGroups().map(g=>`<div class="grid" style="gap:4px"><span class="src"><strong style="color:var(--ink)">${g.n}</strong></span><div class="chips">${g.bs.map(b=>`<button aria-pressed="${w.bldgs.includes(b.k)}"${ed?` onclick="woB('${w.no}','${b.k}')"`:' disabled'}>${bChip(b)}</button>`).join('')}</div></div>`).join('')}
function woEditor(w){const ed=woEditable(w),cost=woCost(w),al=woAlloc(w),p=woParts(w);
  const f=(fld,type,ex='')=>ed?inp(type,w[fld],`woSet('${w.no}','${fld}',this.value)`,ex):`<span>${type==='date'?fdate(w[fld]):esc(w[fld])||'—'}</span>`;
  const line=(kind,cols)=>`<div class="tw"><table class="d"><thead><tr>${cols.map(c=>`<th${c[2]?' class="n"':''}>${c[1]}</th>`).join('')}<th class="n">القيمة</th>${ed?'<th></th>':''}</tr></thead><tbody>
    ${(w[kind]||[]).map((l,i)=>`<tr data-edit>${cols.map(([k,,num])=>`<td${num?' class="n"':''}>${ed?(k==='trade'?`<select data-edit onchange="woLine('${w.no}','${kind}',${i},'trade',this.value)">${TRADES.map(t=>`<option${t===l.trade?' selected':''}>${t}</option>`).join('')}</select>`:`<input data-edit type="${num?'number':'text'}" value="${esc(l[k]??'')}" ${num?'min="0" step="any" style="width:90px"':'style="width:100%"'} onchange="woLine('${w.no}','${kind}',${i},'${k}',this.value)">`):esc(num?nf(l[k],2):l[k])}</td>`).join('')}
    <td class="n">${sar(kind==='labor'?(+l.n||0)*(+l.days||0)*(+l.rate||0):kind==='mats'?(+l.qty||0)*(+l.price||0):(+l.hours||0)*(+l.rate||0))}</td>${ed?`<td><button class="btn sm" onclick="woDelL('${w.no}','${kind}',${i})">حذف</button></td>`:''}</tr>`).join('')}
    </tbody></table></div>${ed?`<button class="btn sm" style="justify-self:start" onclick="woAdd('${w.no}','${kind}')">+ سطر</button>`:''}`;
  const pend=w.status==='pm'||w.status==='sup';
  const apprBox=`<div style="border:1px solid var(--line);border-radius:6px;padding:12px;display:grid;gap:6px">${w.appr?`<span class="pill ok" style="justify-self:start">معتمد</span><span>اعتمده <strong>${esc(w.appr.name)}</strong> <span class="mono src">${esc(w.appr.no||'')}</span> · ${w.appr.at.replace('T',' ').slice(0,16)}</span>`:(w.status==='approved'||w.status==='closed')?'<span class="pill ok" style="justify-self:start">معتمد</span>':pend?`<span class="pill warn" style="justify-self:start">بانتظار الاعتماد</span>${can('sign.pm')?'':'<span class="src">يعتمده صاحب صلاحية «اعتماد أوامر العمل».</span>'}`:'<span class="muted">مسودة – لم يُعتمد بعد</span>'}</div>`;
  return `<section class="card" data-edit><header><div><h3><span class="mono">${w.no}</span> · ${esc(w.title)||'أمر عمل جديد'}</h3><span class="src">أنشأه ${esc(w.by)} · ${fdate(w.date)}</span></div>
   <div class="ctrl"><span class="pill ${WOST[w.status][1]}">${WOST[w.status][0]}</span>${(w.status==='draft'||pend)&&can('sign.pm')?`<button class="btn pri" onclick="woApprove('${w.no}')">اعتماد</button>`:''}${w.status==='draft'&&!can('sign.pm')?`<button class="btn pri"${dis('wo')} onclick="woSend('${w.no}')">إرسال للاعتماد</button>`:''}${w.status==='draft'?`${UI.delArm===w.no?`<button class="btn" style="border-color:var(--crit);color:var(--crit)" onclick="woDel('${w.no}')">تأكيد الحذف</button>`:`<button class="btn"${dis('wo')} onclick="UI.delArm='${w.no}';render()">حذف</button>`}`:''}${w.status==='approved'?`<button class="btn" onclick="woClose('${w.no}')">إغلاق: تم التنفيذ</button>${can('sign.pm')?(UI.delArm==='un:'+w.no?`<button class="btn" style="border-color:var(--crit);color:var(--crit)" onclick="woUnapprove('${w.no}')">تأكيد إلغاء الاعتماد</button>`:`<button class="btn" onclick="UI.delArm='un:${w.no}';render()">إلغاء الاعتماد</button>`):''}`:''}<button class="btn" onclick="woPrint('${w.no}')">النموذج الرسمي</button><button class="btn" onclick="UI.woSel=null;render()">إغلاق</button></div></header>
   ${w.rej&&w.status==='draft'?`<div class="check bad">أعيد للتعديل: ${esc(w.rej)}</div>`:''}
   <div class="form">
    <label class="fld" style="grid-column:span 2"><span>وصف العمل</span>${f('title','text','style="width:100%" placeholder="مثال: لياسة خارجية للواجهة الشمالية"')}</label>
    <label class="fld"><span>التاريخ</span>${f('date','date')}</label>
    <label class="fld"><span>البداية</span>${f('start','date')}</label><label class="fld"><span>النهاية المتوقعة</span>${f('end','date')}</label>
    <label class="fld" style="grid-column:span 2"><span>بند المقايسة</span>${ed?`<select data-edit onchange="woSet('${w.no}','boq',this.value)"><option value="">—</option>${DATA.boq.filter(b=>b.rate.D2>0).map(b=>`<option value="${b.code}"${b.code===w.boq?' selected':''}>${b.code} · ${esc(b.ar.slice(0,45))}</option>`).join('')}</select>`:`<span>${w.boq?w.boq+' · '+esc((item(w.boq)||{ar:''}).ar.slice(0,50)):'—'}</span>`}</label>
    <label class="fld"><span>نسبة إنجاز البند بهذا الأمر %</span>${w.boq&&(w.status==='draft'||w.status==='approved')&&can('wo')&&!RO?inp('number',w.billPct,`woSetBill('${w.no}',this.value)`,'min="0" max="100" step="any" placeholder="0–100"'):`<span>${w.boq?(+w.billPct?nf(+w.billPct,2)+'%':'—'):'اختر البند أولاً'}</span>`}</label>
    <label class="fld" style="grid-column:1/-1"><span>التفاصيل</span>${f('desc','text','style="width:100%"')}</label></div>
   ${w.boq&&+w.billPct>0?`<div class="check good" style="font-size:.84rem">قيمة البند المنجزة بهذا الأمر: ${sar(woPlanned(w))} ر.س (${nf(+w.billPct,2)}% من البند ${w.boq} في ${w.bldgs.length} مبنى، محدودة بالمتبقي غير المفوتر). ${w.status==='closed'?(w.billed?'فُوترت في المستخلص '+w.billed+'.':'قابلة للفوترة الآن.'):'تصبح قابلة للفوترة عند إغلاق الأمر.'}</div>`:''}
   <h3>المباني</h3>${ed?`<div class="chips">${Object.entries(TGT).map(([k,n])=>`<button onclick="woBT('${w.no}','${k}')">${n}</button>`).join('')}</div>`:''}${bldChips(w,ed)}
   <h3>جهة التنفيذ</h3>
   <div class="chips">${[['own','عمالة الشركة – تُحمّل التكلفة على المباني'],['sub','مقاول باطن']].map(([k,n])=>`<button aria-pressed="${w.mode===k}"${ed?` onclick="woSet('${w.no}','mode','${k}')"`:' disabled'}>${n}</button>`).join('')}</div>
   ${w.mode==='sub'?`<div class="form"><label class="fld" style="grid-column:span 2"><span>المقاول</span>${ed?`<select data-edit onchange="woSet('${w.no}','contractor',this.value)"><option value="">اختر المقاول</option>${CONTR.list.filter(c=>c.status!=='done'&&c.status!=='hold'||c.name===w.contractor).map(c=>`<option${c.name===w.contractor?' selected':''}>${esc(c.name)}</option>`).join('')}</select>`:`<span>${esc(w.contractor)||'—'}</span>`}</label>
     <label class="fld"><span>قيمة أعمال المصنعيات للمقاول بدون ضريبة (ر.س)</span>${f('value','number','min="0" step="any"')}</label></div>${ed?`<p class="src" style="margin:0">${CONTR.list.length?'':'لا يوجد مقاولون بعد. '}<button class="btn sm" onclick="go('labor');scNew()">+ إضافة مقاول باطن</button></p>`:''}`
   :`<h3>المصنعيات – عمالة الشركة (العدد × الأيام × الأجر اليومي)</h3>${line('labor',[['trade','المهنة'],['n','العدد',1],['days','الأيام',1],['rate','الأجر اليومي',1]])}`}
   <h3>المواد ${w.mode==='sub'?'(توريد الشركة)':''}</h3>${ed?matPicker(w):''}${line('mats',[['name','المادة'],['unit','الوحدة'],['qty','الكمية',1],['price','سعر الوحدة',1]])}
   <h3>المعدات</h3>${line('equip',[['name','المعدة'],['hours','الساعات',1],['rate','سعر الساعة',1]])}
   <div class="grid g2"><div class="kpi"><span class="lb">تكلفة أمر العمل</span><span class="v">${sar(cost)}</span><span class="s">مصنعيات ${sar(w.mode==='sub'?p.sub:p.labor)}${w.mode==='sub'?' ('+esc(w.contractor||'مقاول')+')':' (عمالة الشركة)'} · مواد ${sar(p.mats)} · معدات ${sar(p.equip)}</span></div>
    <div class="card" style="padding:12px"><span class="src">التحميل على المباني (حسب عدد الوحدات)</span>${al.length?`<table class="d"><tbody>${al.map(a=>`<tr><td class="mono" dir="ltr" style="text-align:right">${esc(BLDK[a.k].plot)}</td><td class="n">${pc(a.share,1)}</td><td class="n">${sar(cost*a.share)}</td></tr>`).join('')}</tbody></table>`:'<span class="muted">اختر المباني</span>'}</div></div>
   <h3>الاعتماد</h3>${apprBox}
   ${pend&&can('sign.pm')?`<div class="ctrl"><input type="text" id="rejNote" placeholder="سبب الرفض" style="min-width:220px"><button class="btn" onclick="woReject('${w.no}')">رفض وإعادة للتعديل</button></div>`:''}
  </section>`}
function woPrint(no){const w=woById(no),al=woAlloc(w),cost=woCost(w);
  openModal(`<div class="vh"><h2>أمر عمل ${w.no}</h2><button class="btn" onclick="closeModal()">إغلاق</button></div><div class="formal"><div class="stripe-head"></div>
   <div class="lh"><img class="lg" src="${LOGO}" alt="أراك الوطنية"><div><strong>${OURCO.name}</strong><br>مقاول باطن لـ${esc(P.contractor)}<br>${esc(P.title)} · عقد ${P.contractNo}</div><div style="text-align:center"><h2>أمر عمل</h2><span class="mono">${w.no}</span></div><div>التاريخ: ${fdate(w.date)}<br>من ${fdate(w.start)} إلى ${w.end?fdate(w.end):'—'}<br>الحالة: ${WOST[w.status][0]}</div></div>
   <div class="tw"><table class="d"><tbody><tr><td style="width:180px;color:var(--muted)">العمل</td><td>${esc(w.title)}${w.desc?'<br>'+esc(w.desc):''}</td></tr><tr><td style="color:var(--muted)">بند المقايسة</td><td>${w.boq?w.boq+' · '+esc(item(w.boq).ar.slice(0,70)):'—'}</td></tr><tr><td style="color:var(--muted)">المباني</td><td dir="ltr" style="text-align:right">${plots(w).join(' ، ')}</td></tr><tr><td style="color:var(--muted)">جهة التنفيذ</td><td>${w.mode==='sub'?'مقاول باطن: '+esc(w.contractor):'عمالة الشركة'}</td></tr><tr><td style="color:var(--muted)">القيمة</td><td>${sar(cost)} ر.س بدون ضريبة</td></tr>
   ${al.map(a=>`<tr><td style="color:var(--muted)">تحميل ${esc(BLDK[a.k].plot)}</td><td>${sar(cost*a.share)} ر.س</td></tr>`).join('')}</tbody></table></div>
   <p style="margin:0">${w.appr?'اعتمده: <strong>'+esc(w.appr.name)+'</strong> · '+fdate(w.appr.at.slice(0,10)):(w.status==='approved'||w.status==='closed')?'معتمد':'غير معتمد بعد'}</p></div></div>`)}

function vSite(){const t=UI.siteTab||'wo';let body='';
  if(t==='wo'){const f=UI.woF||'all',fb=UI.woB||'';const list=WOS.filter(w=>(f==='all'||w.status===f)&&(!fb||w.bldgs.includes(fb)));const sel=UI.woSel&&woById(UI.woSel);
    body=`${sel?woEditor(sel):''}<div class="ctrl"><button class="btn pri"${dis('wo')} onclick="newWo()">+ أمر عمل جديد</button>
      <div class="chips">${[['all','الكل'],...Object.entries(WOST).map(([k,v])=>[k,v[0]])].map(([k,n])=>`<button aria-pressed="${f===k}" onclick="UI.woF='${k}';render()">${n} (${k==='all'?WOS.length:WOS.filter(w=>w.status===k).length})</button>`).join('')}</div>
      <select onchange="UI.woB=this.value;render()"><option value="">كل المباني</option>${bOpts(fb)}</select></div>
    ${list.length?`<div class="tw"><table class="d" id="tWo"><thead><tr><th>الرقم</th><th>التاريخ</th><th>العمل</th><th>المباني</th><th>جهة التنفيذ</th><th class="n">القيمة</th><th>الحالة</th><th>اعتمده</th><th></th></tr></thead><tbody>
