    <div class="tw"><table class="d" id="tBc"><thead><tr><th>المبنى</th><th>النوع</th><th class="n">قيمة المبنى في العقد</th><th class="n">عمالة الشركة</th><th class="n">مواد</th><th class="n">معدات</th><th class="n">مقاولو الباطن</th><th class="n">إجمالي التكلفة</th><th>التكلفة / القيمة</th><th class="n">بانتظار الاعتماد</th><th class="n">أوامر</th></tr></thead><tbody>
    ${rows.map((r,i)=>{const g=bTarget(r.b.k)||'',pg=i?bTarget(rows[i-1].b.k)||'':null,gr=rows.filter(x=>(bTarget(x.b.k)||'')===g);return (g!==pg?`<tr class="grp"><td colspan="2">${TGT[g]||'بدون مستهدف'}</td><td class="n">${sar(gr.reduce((s,x)=>s+x.rev,0))}</td><td colspan="4"></td><td class="n">${sar(gr.reduce((s,x)=>s+x.tot,0))}</td><td></td><td class="n">${sar(gr.reduce((s,x)=>s+x.pend,0))}</td><td></td></tr>`:'')+`<tr class="click" onclick="UI.siteTab='wo';UI.woB='${r.b.k}';render()"><td class="mono" dir="ltr" style="text-align:right">${esc(r.b.plot)}</td><td>${TYK[r.b.t].ar}</td><td class="n">${sar(r.rev)}</td><td class="n">${r.labor?sar(r.labor):'—'}</td><td class="n">${r.mats?sar(r.mats):'—'}</td><td class="n">${r.equip?sar(r.equip):'—'}</td><td class="n">${r.sub?sar(r.sub):'—'}</td><td class="n" style="font-weight:600">${sar(r.tot)}</td><td style="min-width:110px">${meter(r.tot/r.rev*100,r.tot>r.rev?'crit':'')}</td><td class="n">${r.pend?sar(r.pend):'—'}</td><td class="n">${r.n}</td></tr>`}).join('')}
    </tbody><tfoot><tr><td colspan="2">الإجمالي</td><td class="n">${sar(S_('rev'))}</td><td class="n">${sar(S_('labor'))}</td><td class="n">${sar(S_('mats'))}</td><td class="n">${sar(S_('equip'))}</td><td class="n">${sar(S_('sub'))}</td><td class="n">${sar(S_('tot'))}</td><td></td><td class="n">${sar(S_('pend'))}</td><td></td></tr></tfoot></table></div>
    <div class="ctrl"><button class="btn" onclick="copyTable('tBc')">نسخ إلى Excel</button><span class="src">تُحمّل تكلفة أمر العمل على مبانيه بنسبة عدد الوحدات بعد اعتماده. اضغط على مبنى لعرض أوامره.</span></div>`}
  if(t==='lists'){scEnsureIds();body=`<div class="grid g2"><section class="card"><header><h3>مقاولو الباطن</h3><button class="btn sm pri"${canSc()?'':' disabled'} onclick="go('labor');scNew()">+ إضافة مقاول باطن</button></header>
