  ${tabs(t,[['wo','أوامر العمل'],['cost','تكلفة المباني'],['lists','المقاولون وأسعار العمالة']],'siteTab')}${body}`;
}
function siteTab(k){UI.siteTab=k;UI.delArm=null;render()}

/* billable work orders & tasks */
function woBillPctFor(w,bk){const r=Math.max(0,100-prevPct(bk,w.boq,1e9)+(w.billed?0:0));return Math.min(+w.billPct||0,r)}
function woPlanned(w){if(w.billed&&w.billedVal!=null)return w.billedVal;if(!w.boq||!(+w.billPct>0))return 0;return (w.bldgs||[]).filter(k=>BLDK[k]).reduce((s,bk)=>s+woBillPctFor(w,bk)/100*bval(w.boq,BLDK[bk].t),0)}
function woBillable(w){return w.status==='closed'&&!w.billed?woPlanned(w):0}
function woBillableIn(w,bs){if(w.status!=='closed'||w.billed||!w.boq)return 0;return (w.bldgs||[]).filter(k=>bs.includes(k)&&BLDK[k]).reduce((s,bk)=>s+woBillPctFor(w,bk)/100*bval(w.boq,BLDK[bk].t),0)}
function woSetBill(no,v){const w=woById(no);if(!w)return;if(!(w.status==='draft'||w.status==='approved')||!can('wo')){toast('غير متاح في هذه المرحلة','crit');return}
  const val=v===''?'':Math.max(0,Math.min(100,+v||0));if(String(w.billPct??'')===String(val))return;woAct('wo',w,'نسبة إنجاز البند '+w.boq+': '+(val===''?'—':val+'%'),()=>{w.billPct=val})}
function billToIpc(){let d=NIPC.find(x=>x.status==='draft');if(!d){newIpc();d=NIPC.find(x=>x.status==='draft');if(!d)return}
  const ws=WOS.filter(w=>woBillable(w)>0);if(!ws.length){toast('لا توجد بنود قابلة للفوترة','crit');return}
  let n=0;if(ipcAct(d.no,'إضافة '+ws.length+' أمر عمل منجز إلى المستخلص '+d.no,()=>{ws.forEach(w=>{w.billedVal=woPlanned(w);(w.bldgs||[]).filter(k=>BLDK[k]).forEach(bk=>{const p=woBillPctFor(w,bk);if(p<=0)return;const ex=d.lines.find(l=>l.b===bk&&l.code===w.boq);const rem=Math.max(0,100-prevPct(bk,w.boq,d.no)-(ex?+ex.pct:0));const add=Math.min(p,rem);if(add<=0)return;if(ex)ex.pct=Math.round((+ex.pct+add)*100)/100;else d.lines.push({b:bk,code:w.boq,pct:Math.round(add*100)/100,wo:w.no});n++});w.billed=d.no;woSave(w)})})){UI.ipcNo=d.no;go('ipc');toast('أضيف '+n+' سطراً من أوامر العمل إلى المستخلص '+d.no)}}
const TASK_COLS_OLD=[['draft','مسودة – بانتظار الإرسال','wo'],['sup','بانتظار توقيع المشرف','sup'],['pm','بانتظار توقيع مدير المشروع','pm'],['approved','قيد التنفيذ','wo']];
function taskOwner(w){return w.status==='draft'?(w.by||'منشئ الأمر'):w.status==='sup'?'مشرف الموقع':w.status==='pm'?'مدير المشروع':(w.mode==='sub'?esc(w.contractor||'المقاول'):'عمالة الشركة')}
function vTasks(){const mine=UI.taskMine;const open=WOS.filter(w=>w.status!=='closed');
  const isMine=w=>(w.status==='sup'||w.status==='pm')?can('sign.pm'):can('wo');
  const list=mine?open.filter(isMine):open;
  return `<div class="ctrl"><div class="chips"><button aria-pressed="${!mine}" onclick="UI.taskMine=false;render()">كل المهام (${open.length})</button><button aria-pressed="${!!mine}" onclick="UI.taskMine=true;render()">مهامي – ${ROLES[S.role].n} (${open.filter(isMine).length})</button></div><button class="btn pri"${dis('wo')} onclick="UI.siteTab='wo';newWo()">+ أمر عمل جديد</button></div>
   ${open.length?`<div class="grid g4">${TASK_COLS.map(([st,n])=>{const ws=list.filter(w=>w.status===st);return `<section class="card" style="background:var(--surface-2)"><header><h3>${n}</h3><span class="pill">${ws.length}</span></header>
    ${ws.map(w=>{const late=isDate(w.end)&&w.end<TODAY;return `<div class="wo stripe ${late?'crit':st==='approved'?'ok':'warn'}" style="cursor:pointer" onclick="UI.siteTab='wo';UI.woSel='${w.no}';render();window.scrollTo(0,0)">
      <div class="vh"><strong class="mono">${w.no}</strong>${late?`<span class="pill crit">متأخر ${days(w.end,TODAY)} يوم</span>`:w.end?`<span class="pill">حتى ${fdate(w.end)}</span>`:''}</div>
      <div>${esc(w.title)||'—'}</div><div class="src" dir="ltr" style="text-align:right">${plots(w).join('، ')}</div>
      <div class="vh"><span class="src">المسؤول: ${taskOwner(w)}</span><span class="num" style="font-size:.8rem">${sar(woCost(w))}</span></div>
      ${w.boq?`<span class="src">بند ${w.boq}${+w.billPct>0?' · '+nf(+w.billPct,1)+'% من البند · '+sar(woPlanned(w))+' قابل للفوترة عند الإغلاق':''}</span>`:''}</div>`}).join('')||'<p class="muted" style="margin:0;font-size:.84rem">لا توجد مهام.</p>'}</section>`}).join('')}</div>`
   :empty('لا توجد مهام مفتوحة','كل أمر عمل لم يُغلق يظهر هنا كمهمة حسب مرحلته، مع المسؤول عنها وتاريخ نهايتها.')}`}

/* completed targets (in defects-liability / maintenance period) */
const WARR=['34','35'];
const DONE_P=0.9; // items at or above this certified progress count as finished
const tDone=t=>(SCH.targets.done||[]).includes(t);
function toggleDone(t){const on=!tDone(t);schAct('targets',(TGT[t]||t)+': '+(on?'منتهي – فترة الضمان والصيانة':'إعادة فتح كمستهدف جارٍ'),()=>{const d=SCH.targets.done||[];SCH.targets.done=on?[...new Set([...d,t])]:d.filter(x=>x!==t)})}
/* materials consumed per building = quantity tables × unit price (counted as spent for completed targets) */
let QCB={},QCB_K='';
function qtyCostB(bk){const key=JSON.stringify(PRICES.p)+'|'+DATA.qtyTables.length;if(key!==QCB_K){QCB={};QCB_K=key}
  if(QCB[bk])return QCB[bk];let v=0,n=0,m=0;DATA.qtyTables.forEach((t,i)=>t.rows.forEach((r,j)=>{const q=qtyFor(t,r,[bk]);if(!q)return;const pr=priceOf(i,j);if(pr!==''){v+=q*pr;n++}else m++}));return QCB[bk]={v,n,m}}
const matSpentB=bk=>tDone(bTarget(bk))?qtyCostB(bk).v:0;
function doneSummary(bs){let wv=0,wc=0,ov=0,oc=0;DATA.boq.forEach(it=>{const A=bs.reduce((s,b)=>s+bval(it.code,BLDK[b].t),0),C=bs.reduce((s,b)=>s+certVal(b,it.code),0);if(WARR.includes(it.code)){wv+=A;wc+=C}else{ov+=A;oc+=C}});
  return {wv,wc,wrem:wv-wc,ov,oc,orem:ov-oc,val:wv+ov,cert:wc+oc}}
function doneCost(bs){const r={labor:0,mats:0,equip:0,sub:0,pend:0,warr:0,n:0};WOS.forEach(w=>{const al=woAlloc(w).filter(a=>bs.includes(a.k));if(!al.length)return;const sh=al.reduce((s,a)=>s+a.share,0),p=woParts(w);
  if(w.status==='approved'||w.status==='closed'){r.labor+=p.labor*sh;r.mats+=p.mats*sh;r.equip+=p.equip*sh;r.sub+=p.sub*sh;r.n++;if(WARR.includes(w.boq))r.warr+=woCost(w)*sh}else r.pend+=woCost(w)*sh});r.qmat=bs.reduce((s,b)=>s+matSpentB(b),0);r.tot=r.labor+r.mats+r.equip+r.sub+r.qmat;return r}
function donePanel(g){const bs=g.bs.map(b=>b.k),d=doneSummary(bs),c=doneCost(bs),ret=IPC.lines.retention[2]*(d.cert/(IPC.lines.total[2]||1)),mg=d.cert-c.tot;
  return `<div class="grid" style="gap:8px"><div class="vh" style="align-items:center"><strong>${g.n}</strong><span class="pill ok">منتهي – فترة الضمان والصيانة</span></div>
   <span class="src">${bs.length} مبنى · ${g.bs.reduce((s,b)=>s+b.units.length,0)} وحدة · <span dir="ltr">${g.bs.map(b=>esc(b.plot)).join('، ')}</span></span>
   <div class="grid g4"><div class="kpi"><span class="lb">المعتمد (الإيراد)</span><span class="v">${nf(d.cert/1e6,3)}<small> مليون</small></span><span class="s">${nf(d.cert/d.val*100,1)}% من قيمة المستهدف</span></div>
    <div class="kpi"><span class="lb">التكلفة الحالية</span><span class="v">${sar(c.tot)}</span><span class="s">مواد جداول الكميات ${sar(c.qmat)} · ${c.n} أمر عمل${c.pend?' · بانتظار الاعتماد '+sar(c.pend):''}</span></div>
    <div class="kpi"><span class="lb">التكلفة / المعتمد</span><span class="v" style="color:var(--${c.tot>d.cert?'crit':'ink'})">${nf(d.cert?c.tot/d.cert*100:0,1)}<small>%</small></span><span class="s">منها ضمان وصيانة ${sar(c.warr)}</span></div>
    <div class="kpi"><span class="lb">الهامش الحالي</span><span class="v" style="color:var(--${mg<0?'crit':'ok'})">${sar(mg)}</span><span class="s">المعتمد − التكلفة</span></div></div>
   <div class="tw"><table class="d"><thead><tr><th>البيان</th><th class="n">القيمة</th><th class="n">المعتمد</th><th class="n">المتبقي للفوترة</th><th class="n">التكلفة الحالية</th><th>الحالة</th></tr></thead><tbody>
    <tr><td>كل بنود التنفيذ (${DATA.boq.filter(it=>it.rate.D2>0&&!WARR.includes(it.code)).length} بنداً)</td><td class="n">${sar(d.ov)}</td><td class="n">${sar(d.oc)}</td><td class="n">${sar(d.orem)}</td><td class="n">${sar(c.tot-c.warr)}</td><td><span class="pill ok">منفذة 100%</span></td></tr>
    <tr><td>فترة مسؤولية العيوب والضمانات (بند 34 و35)</td><td class="n">${sar(d.wv)}</td><td class="n">${sar(d.wc)}</td><td class="n">${sar(d.wrem)}</td><td class="n">${sar(c.warr)}</td><td><span class="pill warn">جارية</span></td></tr>
    <tr><td>محتجز الضمان التقديري لمباني المستهدف (10%)</td><td></td><td></td><td class="n">${sar(ret)}</td><td></td><td><span class="pill">يُفرج عنه بعد فترة الصيانة</span></td></tr>
   </tbody><tfoot><tr><td>الإجمالي</td><td class="n">${sar(d.val)}</td><td class="n">${sar(d.cert)}</td><td class="n">${sar(d.orem+d.wrem)}</td><td class="n">${sar(c.tot)}</td><td></td></tr></tfoot></table></div>
   <div class="tw"><table class="d"><thead><tr><th>تفصيل التكلفة الحالية</th><th class="n">مصنعيات عمالة الشركة</th><th class="n">مقاولو الباطن</th><th class="n">مواد</th><th class="n">معدات</th><th class="n">الإجمالي</th></tr></thead><tbody><tr><td>أوامر العمل المعتمدة والمنفذة</td><td class="n">${sar(c.labor)}</td><td class="n">${sar(c.sub)}</td><td class="n">${sar(c.mats)}</td><td class="n">${sar(c.equip)}</td><td class="n">${sar(c.tot-c.qmat)}</td></tr>
    <tr><td>مواد جداول الكميات لمباني المستهدف (منصرف)${(()=>{const mm=DATA.qtyTables.reduce((n,t,i)=>n+t.rows.filter((r,j)=>priceOf(i,j)===''&&qtyFor(t,r,bs)>0).length,0);return mm?` <span class="src">· ${mm} صنفاً بلا سعر غير محسوب</span>`:''})()}</td><td></td><td></td><td class="n">${sar(c.qmat)}</td><td></td><td class="n">${sar(c.qmat)}</td></tr></tbody><tfoot><tr><td>الإجمالي</td><td class="n">${sar(c.labor)}</td><td class="n">${sar(c.sub)}</td><td class="n">${sar(c.mats+c.qmat)}</td><td class="n">${sar(c.equip)}</td><td class="n" style="font-weight:600">${sar(c.tot)}</td></tr></tfoot></table></div>
   <p class="src" style="margin:0">التكلفة الحالية = كل كميات جداول الكميات لمباني المستهدف المنجز × سعر الوحدة (تُعتبر منصرفة) + نصيب مبانيه من أوامر العمل. الأصناف بلا سعر لا تُحسب حتى يُدخل سعرها من جداول الكميات (زر «إظهار الأسعار»). أي أمر عمل صيانة أو ضمان يُربط ببند 34 أو 35 ويُحسب هنا. ${can('sched')?`<button class="btn sm" onclick="toggleDone('${g.t}')">إعادة فتح المستهدف</button>`:''}</p></div>`}

/* works in progress by target */
function wipFor(bs){return DATA.boq.filter(it=>it.rate.D2>0).map(it=>{
  const A=bs.reduce((s,b)=>s+bval(it.code,BLDK[b].t),0),C=bs.reduce((s,b)=>s+certVal(b,it.code),0);
  let cost=0,open=0,plan=0,bill=0,n=0;
  WOS.filter(w=>w.boq===it.code).forEach(w=>{const al=woAlloc(w).filter(a=>bs.includes(a.k));if(!al.length)return;n++;const sh=al.reduce((s,a)=>s+a.share,0);
