  const sel=UI.tkSel&&tkById(UI.tkSel);
  const cnt=k=>all.filter(t=>t.status===k).length,lateN=all.filter(tkLate).length,week=all.filter(t=>t.status!=='done'&&isDate(t.due)&&t.due>=TODAY&&days(TODAY,t.due)<=7).length;
  const view=UI.tkView||'board';
