  else {const k=UI.tkSort||'due';list=list.slice().sort((a,b)=>k==='prio'?PRIO[a.prio][2]-PRIO[b.prio][2]:k==='status'?TK_ST.findIndex(x=>x[0]===a.status)-TK_ST.findIndex(x=>x[0]===b.status):String(a.due||'9').localeCompare(String(b.due||'9')));
    body=`<div class="tw"><table class="d" id="tTk"><thead><tr><th>الرقم</th><th>المصدر</th><th>المهمة</th><th>المسؤول</th><th>المباني</th><th>الأولوية</th><th>الحالة</th><th>الإنجاز</th><th>الاستحقاق</th></tr></thead><tbody>
    ${list.map(t=>`<tr class="click" onclick="tkOpen('${t.id}')"><td class="mono">${t.id}</td><td><span class="pill ${t.src==='man'?'':'acc'}">${t.src==='man'?'يدوية':'أمر عمل'}</span></td><td>${esc(t.title)||'—'}</td><td>${asgLabel(t)}</td><td class="mono" dir="ltr" style="text-align:right">${t.bldgs.filter(x=>BLDK[x]).map(x=>BLDK[x].plot).join('، ')||'—'}</td><td><span class="pill ${PRIO[t.prio][1]}">${PRIO[t.prio][0]}</span></td><td>${TK_STN[t.status]}</td><td style="min-width:100px">${meter(t.prog,t.status==='done'?'ok':'')}<span class="num" style="font-size:.74rem">${t.prog}%</span></td><td>${t.due?`<span class="pill ${tkLate(t)?'crit':''}">${fdate(t.due)}</span>`:'—'}</td></tr>`).join('')}
    </tbody></table></div><button class="btn" style="justify-self:start" onclick="copyTable('tTk')">نسخ إلى Excel</button>`}
  return `<div class="vh"><div><h2>إدارة المهام</h2><p>مهام أوامر العمل تُنشأ تلقائياً وتتبع مراحل الأمر، والمهام اليدوية تضيفها وتتابعها بالمسؤول والأولوية والاستحقاق والبنود الفرعية.</p></div><button class="btn pri"${canTask()?'':' disabled'} onclick="newTask()">+ مهمة جديدة</button></div>
  <div class="grid g4">
   <div class="kpi"><span class="lb">مهام مفتوحة</span><span class="v">${all.length-cnt('done')}</span><span class="s">جديدة ${cnt('new')} · قيد التنفيذ ${cnt('doing')} · بانتظار ${cnt('wait')}</span></div>
