   <div class="kpi"><span class="lb">مكتملة</span><span class="v">${cnt('done')}</span><span class="s">يدوية ${TASKS.filter(t=>t.status==='done').length} · أوامر عمل ${WOS.filter(w=>w.status==='closed').length}</span></div>
  </div>
  ${sel?tkEditor(sel):''}
  <div class="ctrl">
   <div class="chips"><button aria-pressed="${view==='board'}" onclick="UI.tkView='board';render()">لوحة</button><button aria-pressed="${view==='list'}" onclick="UI.tkView='list';render()">قائمة</button></div>
   <div class="chips"><button aria-pressed="${!UI.tkMine}" onclick="UI.tkMine=false;render()">كل المهام</button><button aria-pressed="${!!UI.tkMine}" onclick="UI.tkMine=true;render()">مهامي (${all.filter(t=>isMine(t)&&t.status!=='done').length})</button></div>
   <select onchange="UI.tkF={...(UI.tkF||{}),src:this.value};render()"><option value="">كل المصادر</option><option value="man"${F.src==='man'?' selected':''}>يدوية</option><option value="wo"${F.src==='wo'?' selected':''}>أوامر العمل</option></select>
   <select onchange="UI.tkF={...(UI.tkF||{}),prio:this.value};render()"><option value="">كل الأولويات</option>${Object.entries(PRIO).map(([k,v])=>`<option value="${k}"${F.prio===k?' selected':''}>${v[0]}</option>`).join('')}</select>
   <select onchange="UI.tkF={...(UI.tkF||{}),b:this.value};render()"><option value="">كل المباني</option>${bOpts(F.b)}</select>
   <label style="display:flex;gap:6px;align-items:center;font-size:.84rem"><input type="checkbox"${F.late?' checked':''} onchange="UI.tkF={...(UI.tkF||{}),late:this.checked};render()"> المتأخرة فقط</label>
   <input type="text" placeholder="بحث" value="${esc(F.q||'')}" onchange="UI.tkF={...(UI.tkF||{}),q:this.value};render()" style="min-width:150px">
   ${view==='list'?`<select onchange="UI.tkSort=this.value;render()">${[['due','ترتيب: الاستحقاق'],['prio','ترتيب: الأولوية'],['status','ترتيب: الحالة']].map(([k,n])=>`<option value="${k}"${(UI.tkSort||'due')===k?' selected':''}>${n}</option>`).join('')}</select>`:''}
  </div>
  ${all.length?body:empty('لا توجد مهام بعد','أضف مهمة يدوية، أو أنشئ أمر عمل من شاشة الموقع ليظهر هنا كمهمة تلقائياً.')}`;
}

