const modLv=()=>1,isAdmin=()=>false;function restoreSession(){S.role='cons';RO=true}function vUsers(){return ''}function vLogin(){return ''}function logout(){}
/* ---------- subcontractors register ---------- */
const SC_ST={active:['نشط','ok'],hold:['موقوف','warn'],done:['منتهي','']};
const scList=()=>CONTR.list;
const scById=id=>CONTR.list.find(c=>c.id===id);
function scEnsureIds(){let n=CONTR.list.reduce((m,c)=>Math.max(m,+String(c.id||'').replace(/\D/g,'')||0),0);CONTR.list.forEach(c=>{if(!c.id)c.id='SC-'+String(++n).padStart(2,'0');c.bldgs=c.bldgs||[];c.boq=c.boq||[];if(!c.status)c.status='active'})}
const canSc=()=>(can('labor')||can('wo'))&&!RO;
const scSave=()=>saveDoc('lists','contractors',()=>CONTR);
const scAct=(c,label,fn)=>{if(!canSc()){toast(RO?'هذه الصفحة للقراءة فقط بالنسبة لك':'لا تملك صلاحية إدارة مقاولي الباطن','crit');return false}return act(null,'مقاول الباطن '+(c?c.name:'')+' · '+label,()=>{const r=fn();if(r===false)return false;scSave()})};
function scStats(c){const ws=WOS.filter(w=>w.mode==='sub'&&w.contractor===c.name),ap=ws.filter(w=>w.status==='approved'||w.status==='closed'),cl=ws.filter(w=>w.status==='closed');
  const wv=w=>+w.value||0;const apv=ap.reduce((s,w)=>s+wv(w),0),clv=cl.reduce((s,w)=>s+wv(w),0),pend=ws.filter(w=>w.status==='sup'||w.status==='pm').reduce((s,w)=>s+wv(w),0);
  const val=+c.value||0;return {ws,n:ws.length,apv,clv,pend,rem:val?val-apv:null,ret:clv*(+c.ret||0)/100,use:val?apv/val:null}}
function scNew(){scEnsureIds();const n=CONTR.list.reduce((m,c)=>Math.max(m,+String(c.id||'').replace(/\D/g,'')||0),0)+1,id='SC-'+String(n).padStart(2,'0');
  const c={id,name:'مقاول باطن جديد',cr:'',vat:'',contact:'',phone:'',email:'',scope:'',boq:[],bldgs:[],value:'',ret:10,adv:0,start:TODAY,end:'',status:'active',notes:''};
  if(scAct(c,'إضافة',()=>{CONTR.list.push(c)})){UI.scSel=id;render();window.scrollTo(0,0)}}
function scSet(id,f,v){const c=scById(id);if(!c)return;let val=['value','ret','adv'].includes(f)?(v===''?'':Math.max(0,+v||0)):String(v).trim();
  if((f==='ret'||f==='adv')&&val>100){toast('النسبة بين 0 و 100','crit');render();return}
  if(f==='name'){if(!val){toast('اسم المقاول مطلوب','crit');render();return}if(CONTR.list.some(x=>x!==c&&x.name===val)){toast('يوجد مقاول بنفس الاسم','crit');render();return}}
  if(f==='end'&&val&&c.start&&val<c.start){toast('تاريخ النهاية قبل البداية','crit');render();return}
  if(String(c[f]??'')===String(val))return;const old=c[f];
  const lbl={name:'الاسم',cr:'السجل التجاري',vat:'الرقم الضريبي',contact:'المسؤول',phone:'الجوال',email:'البريد',scope:'نطاق العمل',value:'قيمة العقد',ret:'المحتجز %',adv:'الدفعة المقدمة %',start:'البداية',end:'النهاية',status:'الحالة',notes:'ملاحظات'}[f];
  scAct(c,lbl+': '+(f==='status'?SC_ST[val][0]:val===''?'—':val),()=>{c[f]=val;if(f==='name'){WOS.filter(w=>w.contractor===old).forEach(w=>{w.contractor=val;woSave(w)})}})}
function scB(id,bk){const c=scById(id);const has=c.bldgs.includes(bk);scAct(c,(has?'إزالة':'إضافة')+' المبنى '+BLDK[bk].plot,()=>{c.bldgs=has?c.bldgs.filter(x=>x!==bk):[...c.bldgs,bk]})}
function scBT(id,t,on){const c=scById(id);const ks=bGroups().find(g=>g.t===t).bs.map(b=>b.k);scAct(c,(on?'إسناد ':'إلغاء إسناد ')+(TGT[t]||'مباني بدون مستهدف'),()=>{c.bldgs=on?[...new Set([...c.bldgs,...ks])]:c.bldgs.filter(k=>!ks.includes(k))})}
function scBoq(id,code,on){const c=scById(id);if(!code)return;scAct(c,(on?'إضافة':'إزالة')+' البند '+code,()=>{c.boq=on?[...new Set([...c.boq,code])]:c.boq.filter(x=>x!==code)})}
function scDel(id){const c=scById(id);UI.delArm=null;if(!c)return;if(WOS.some(w=>w.contractor===c.name)){toast('لا يمكن حذف مقاول له أوامر عمل. غيّر حالته إلى «منتهي» بدلاً من ذلك.','crit');return}
  if(scAct(c,'حذف',()=>{CONTR.list=CONTR.list.filter(x=>x.id!==id);UI.scSel=null}))render()}
function scNewWo(id){const c=scById(id);if(!can('wo')){toast('لا تملك صلاحية إنشاء أوامر العمل','crit');return}newWo();const no=UI.woSel;const w=woById(no);if(!w)return;
  woAct('wo',w,'إسناد إلى '+c.name,()=>{w.mode='sub';w.contractor=c.name;w.bldgs=[...c.bldgs];w.boq=c.boq[0]||'';w.labor=[]});UI.siteTab='wo';go('site')}
