    <label class="fld"><span>البريد</span>${f('email','text','dir="ltr" inputmode="email"')}</label>
    <label class="fld"><span>الحالة</span>${ed?`<select data-edit onchange="scSet('${c.id}','status',this.value)">${Object.entries(SC_ST).map(([k,v])=>`<option value="${k}"${k===c.status?' selected':''}>${v[0]}</option>`).join('')}</select>`:SC_ST[c.status][0]}</label>
    <label class="fld" style="grid-column:1/-1"><span>نطاق العمل</span>${f('scope','text','style="width:100%" placeholder="مثال: لياسة وبلوك للمستهدف الرابع"')}</label>
    <label class="fld"><span>قيمة العقد بدون ضريبة (ر.س)</span>${f('value','number','min="0" step="any"')}</label>
    <label class="fld"><span>المحتجز %</span>${f('ret','number','min="0" max="100" step="any"')}</label>
    <label class="fld"><span>الدفعة المقدمة %</span>${f('adv','number','min="0" max="100" step="any"')}</label>
    <label class="fld"><span>تاريخ البداية</span>${f('start','date')}</label>
    <label class="fld"><span>تاريخ النهاية</span>${f('end','date')}</label>
    <label class="fld" style="grid-column:1/-1"><span>ملاحظات</span>${f('notes','text','style="width:100%"')}</label></div>
