function supAct(label,fn){if(!canSup()){toast(RO?'هذه الصفحة للقراءة فقط بالنسبة لك':'لا تملك صلاحية تعديل جدول التوريدات','crit');return false}return act(null,'جدول التوريدات · '+label,()=>{const r=fn();if(r===false)return false;supSave()})}
const tgtOfSch=K=>K==='m3'?'T3':'T4';
function supBuild(key,K,r,manual){const M=SCH[K]||{},o=manual||SUP.rows[key]||{},bs=(SCH.targets[tgtOfSch(K)]||[]).filter(b=>BLDK[b]);
  const def=manual?[]:(SUP_MAP.find(m=>(r.ar||'').includes(m[0]))||[null,[]])[1];
  const tbls=o.tbls||def,lead=o.lead!=null&&o.lead!==''?+o.lead:+SUP.lead||0;
  const need=isDate(o.need)?o.need:isDate(r.start)?r.start:isDate(r.finish)?r.finish:(isDate(M.due)?M.due:'');
  const orderBy=need?addD(need,-lead):'';const delivered=o.st==='delivered'||r.matDate==='Delivered'||(r.total>0&&(+r.mat||0)>=r.total);
  const st=delivered?'delivered':(o.st||((+r.mat||0)>0||isDate(r.matDate)?'ordered':'pending'));
  const val=tbls.reduce((s,i)=>{const t=DATA.qtyTables[i];if(!t)return s;return s+t.rows.reduce((x,row,j)=>{const p=priceOf(i,j),q=qtyFor(t,row,bs);return x+(p!==''?q*p:0)},0)},0)+(manual&&+manual.price?(+manual.total||0)*(+manual.price):0);
  return {key,K,r,o,manual:!!manual,name:o.name||r.ar,bs,tbls,lead,need,orderBy,st,delivered,eta:isDate(r.matDate)?r.matDate:'',val,sup:o.sup||'',po:o.po||'',note:o.note||'',late:!delivered&&need&&need<TODAY,orderNow:!delivered&&st==='pending'&&orderBy&&orderBy<=addD(TODAY,7)}}
function supAll(){const out=[];['m3','m4'].forEach(K=>{const M=SCH[K];if(!M)return;M.rows.forEach(r=>{if(!(r.total>0))return;out.push(supBuild(K+':'+r.id,K,r))})});
  SUP.manual.forEach(m=>{out.push(supBuild('x:'+m.id,m.K,{ar:m.name,total:+m.total||0,mat:m.mat,matDate:m.eta||'',start:m.need,remark:m.note},m))});return out}
