       <td>${x.orderBy&&!x.delivered?`<span class="pill ${x.orderBy<TODAY?'crit':x.orderNow?'warn':''}">${fdate(x.orderBy)}</span>`:'—'}</td>
       <td>${x.delivered?'<span class="pill ok">تم</span>':x.eta?fdate(x.eta):'—'}</td>
       <td><span class="pill ${SUP_ST[x.st][1]}">${SUP_ST[x.st][0]}</span></td>
       <td>${lk||'<span class="muted">—</span>'}${ed?`<select data-edit onchange="supTbl('${x.key}',+this.value,true);this.value=''" style="font-size:.74rem;max-width:110px"><option value="">+ ربط</option>${DATA.qtyTables.map((tt,i)=>x.tbls.includes(i)?'':`<option value="${i}">${esc(tt.sheet)}</option>`).join('')}</select>`:''}</td>
       <td class="n">${x.val?sar(x.val):'—'}</td><td>${esc([x.sup,x.po].filter(Boolean).join(' · ')||'—')}</td>
       ${ed?`<td style="white-space:nowrap"><button class="btn sm" onclick="UI.supEdit=${UI.supEdit===x.key?'null':`'${x.key}'`};UI.delArm=null;render()">${UI.supEdit===x.key?'إغلاق':'تعديل'}</button> ${UI.delArm==='sup:'+x.key&&UI.supEdit!==x.key?`<button class="btn sm" style="border-color:var(--crit);color:var(--crit)" onclick="supDel('${x.key}')">تأكيد</button>`:`<button class="btn sm" onclick="UI.delArm='sup:${x.key}';render()">حذف</button>`}</td>`:''}</tr>`;
      return row+(UI.supEdit===x.key&&ed?supEditor(x):'')}).join('')}
    </tbody></table></div><button class="btn sm" style="justify-self:start" onclick="copyTable('tSup')">نسخ إلى Excel</button>
    ${hidden.length?`<details><summary class="src" style="cursor:pointer">مواد محذوفة من جدول التوريدات (${hidden.length})</summary><div class="list">${hidden.map(x=>`<div class="li"><div class="t">${esc(x.name)}<small>${x.K==='m3'?'المستهدف الثالث':'المستهدف الرابع'} · ما زالت في الجدول الزمني</small></div>${ed?`<button class="btn sm" onclick="supRestore('${x.key}')">استعادة</button>`:''}</div>`).join('')}</div></details>`:''}
    <p class="src" style="margin:0">«حذف» لمادة من الجدول الزمني يخفيها من جدول التوريدات فقط ويمكن استعادتها، أما المادة المضافة يدوياً فتُحذف نهائياً. تعديل «المورّد» و«موعد التوريد» لمادة من الجدول الزمني يحدّث الجدول الزمني أيضاً.</p>`
    :empty('لا توجد مواد مطابقة',ed?'غيّر المرشحات، أو أضف مادة يدوياً.':'غيّر المرشحات أعلاه.')}
  if(t==='req'){const TGs=TG==='all'?['m3','m4']:[TG];const hid=[];
    body=TGs.map(K=>{const tk=tgtOfSch(K),bs=(SCH.targets[tk]||[]).filter(b=>BLDK[b]),Ls=supLines().filter(x=>x.K===K);
      const rows=DATA.qtyTables.map((tt,i)=>{const it=tt.rows.map((row,j)=>({q:qtyFor(tt,row,bs),p:priceOf(i,j)}));const q=it.reduce((s,x)=>s+x.q,0),v=it.reduce((s,x)=>s+(x.p!==''?x.q*x.p:0),0),pr=it.filter(x=>x.q>0&&x.p!=='').length,n=it.filter(x=>x.q>0).length;
        const acts=Ls.filter(x=>x.tbls.includes(i)),o=(SUP.tbl[K+':'+i]||{}),need=o.need||(acts.map(x=>x.need).filter(Boolean).sort()[0])||SCH[K].due||'',lead=+SUP.lead||0,ob=need?addD(need,-lead):'',st=o.st||'pending';
        return {tt,i,q,v,pr,n,acts,need,ob,st,o,k:K+':'+i}}).filter(x=>x.n>0);
      rows.filter(x=>x.o.hidden).forEach(x=>hid.push({K,x}));const vis=rows.filter(x=>!x.o.hidden);
      return `<section class="card"><header><div><h3>طلبات الشراء – ${TGT[tk]}</h3><span class="src">${bs.length} مبنى · الكميات من جداول الكميات لمباني المستهدف</span></div></header>
      <div class="tw"><table class="d" id="tSupR${K}"><thead><tr><th>جدول الكميات</th><th class="n">أصناف</th><th class="n">إجمالي الكميات</th><th class="n">القيمة</th><th>مسعّر</th><th>الأنشطة المرتبطة</th><th>تاريخ الحاجة</th><th>آخر موعد للطلب</th><th>الحالة</th><th>المورد / أمر الشراء</th>${ed?'<th></th>':''}</tr></thead><tbody>
      ${vis.map(x=>{const ee=UI.supEdit==='r:'+x.k&&ed;return `<tr data-edit${ee?' class="sel"':''}><td><button class="btn sm" onclick="setQSel([...SCH.targets['${tk}']]);UI.qty=${x.i};go('qty')">${esc(x.tt.sheet)}</button></td><td class="n">${x.n}</td><td class="n">${nf(x.q)}</td><td class="n">${x.v?sar(x.v):'—'}</td><td>${meter(x.n?x.pr/x.n*100:0,x.pr===x.n?'ok':'warn')}<span class="num" style="font-size:.72rem">${x.pr}/${x.n}</span></td>
       <td>${x.acts.map(a=>`<span class="pill">${esc(a.name)}</span>`).join(' ')||'<span class="muted">—</span>'}</td>
       <td>${ee?`<input data-edit type="date" value="${esc(x.o.need||'')}" onchange="supTblSet('${x.k}','need',this.value)">`:(x.need?fdate(x.need):'—')}</td>
       <td>${x.ob&&x.st!=='delivered'?`<span class="pill ${x.ob<TODAY?'crit':x.ob<=addD(TODAY,7)?'warn':''}">${fdate(x.ob)}</span>`:'—'}</td>
       <td>${ee?`<select data-edit onchange="supTblSet('${x.k}','st',this.value)">${Object.entries(SUP_ST).map(([s,v])=>`<option value="${s}"${s===x.st?' selected':''}>${v[0]}</option>`).join('')}</select>`:`<span class="pill ${SUP_ST[x.st][1]}">${SUP_ST[x.st][0]}</span>`}</td>
       <td>${ee?`<input data-edit type="text" value="${esc(x.o.sup||'')}" placeholder="المورد" style="width:110px" onchange="supTblSet('${x.k}','sup',this.value)"> <input data-edit type="text" value="${esc(x.o.po||'')}" placeholder="PO" style="width:80px" onchange="supTblSet('${x.k}','po',this.value)">`:esc([x.o.sup,x.o.po].filter(Boolean).join(' · ')||'—')}</td>
       ${ed?`<td style="white-space:nowrap"><button class="btn sm" onclick="UI.supEdit=${ee?'null':`'r:${x.k}'`};UI.delArm=null;render()">${ee?'تم':'تعديل'}</button> ${UI.delArm==='supr:'+x.k?`<button class="btn sm" style="border-color:var(--crit);color:var(--crit)" onclick="UI.delArm=null;supTblSet('${x.k}','hidden',true)">تأكيد</button>`:`<button class="btn sm" onclick="UI.delArm='supr:${x.k}';render()">حذف</button>`}</td>`:''}</tr>`}).join('')}
      </tbody><tfoot><tr><td>الإجمالي</td><td></td><td></td><td class="n">${sar(vis.reduce((s,x)=>s+x.v,0))}</td><td colspan="${ed?7:6}"></td></tr></tfoot></table></div></section>`}).join('')+
      (hid.length?`<details><summary class="src" style="cursor:pointer">طلبات محذوفة من القائمة (${hid.length})</summary><div class="list">${hid.map(({K,x})=>`<div class="li"><div class="t">${esc(x.tt.sheet)}<small>${K==='m3'?'المستهدف الثالث':'المستهدف الرابع'}</small></div>${ed?`<button class="btn sm" onclick="supTblSet('${x.k}','hidden',false)">استعادة</button>`:''}</div>`).join('')}</div></details>`:'')+
      `<p class="src" style="margin:0">تاريخ الحاجة الافتراضي = أقرب تاريخ حاجة للأنشطة المرتبطة، أو تاريخ استحقاق المستهدف. «حذف» يخفي الطلب من القائمة ولا يغيّر جدول الكميات، ويمكن استعادته.</p>`}
  return `<div class="vh"><div><h2>جدول التوريدات</h2><p>مواد الجدول الزمني وطلبات الشراء لكل مستهدف، مرتبطة بجداول الكميات وأسعار الموردين، مع آخر موعد للطلب حسب مدة التوريد إلى فرسان.</p></div></div>
  ${kp}${tabs(t,[['sched','مواد الجدول الزمني'],['req','طلبات الشراء حسب المستهدف']],'supTabSet')}${ctrls}${body}`}
function supTabSet(k){UI.supTab=k;UI.supEdit=null;UI.delArm=null;render()}



