/* ---------- modal & export ---------- */
function openModal(h){$('#modalBox').innerHTML=h;$('#modal').hidden=false}
function closeModal(){$('#modal').hidden=true}
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
function copyTable(id){const t=document.getElementById(id);if(!t)return;
  const txt=[...t.querySelectorAll('tr')].map(tr=>[...tr.children].map(c=>c.innerText.replace(/\s+/g,' ').trim()).join('\t')).join('\n');
  const fb=()=>{openModal(`<div class="vh"><h2>انسخ النص والصقه في Excel</h2><button class="btn" onclick="closeModal()">إغلاق</button></div><textarea id="cpTxt" rows="12" style="width:100%">${esc(txt)}</textarea>`);const a=$('#cpTxt');a.focus();a.select()};
  try{navigator.clipboard.writeText(txt).then(()=>toast('نُسخ الجدول. الصقه مباشرة في Excel.'),fb)}catch(e){fb()}}

restoreSession();
const h0=(location.hash||'').slice(1);if(NAV.some(n=>n[0]===h0))S.view=h0;
render();
